/// Compiled branching model.
pub struct Model {
    pub persistence: Vec<Regex>,
    pub order: Vec<Regex>,
    pub terminal_colors: Vec<(Regex, Vec<String>)>,
    pub terminal_colors_unknown: Vec<String>,
    pub svg_colors: Vec<(Regex, Vec<String>)>,
    pub svg_colors_unknown: Vec<String>,
}

impl Model {
    pub fn compile(def: ModelDef) -> Result<Model, regex::Error> {
        let persistence = def
            .persistence
            .iter()
            .map(|s| Regex::new(s))
            .collect::<Result<Vec<_>, _>>()?;
        let order = def
            .order
            .iter()
            .map(|s| Regex::new(s))
            .collect::<Result<Vec<_>, _>>()?;
        let terminal_colors = def
            .terminal_colors
            .matches
            .into_iter()
            .map(|(s, c)| Regex::new(&s).map(|r| (r, c)))
            .collect::<Result<Vec<_>, _>>()?;
        let svg_colors = def
            .svg_colors
            .matches
            .into_iter()
            .map(|(s, c)| Regex::new(&s).map(|r| (r, c)))
            .collect::<Result<Vec<_>, _>>()?;
        Ok(Model {
            persistence,
            order,
            terminal_colors,
            terminal_colors_unknown: def.terminal_colors.unknown,
            svg_colors,
            svg_colors_unknown: def.svg_colors.unknown,
        })
    }
}

/// Patterns used to extract branch names from merge commit summaries.
pub struct MergePatterns {
    pub patterns: Vec<Regex>,
}

impl Default for MergePatterns {
    fn default() -> Self {
        MergePatterns {
            patterns: vec![
                // GitLab pull request
                Regex::new(r"^Merge branch '(.+)' into '.+'$").unwrap(),
                // Git default
                Regex::new(r"^Merge branch '(.+)' into .+$").unwrap(),
                // Git default into main branch
                Regex::new(r"^Merge branch '(.+)'$").unwrap(),
                // GitHub pull request
                Regex::new(r"^Merge pull request #[0-9]+ from .[^/]+/(.+)$").unwrap(),
                // GitHub pull request (from fork?)
                Regex::new(r"^Merge branch '(.+)' of .+$").unwrap(),
                // BitBucket pull request
                Regex::new(r"^Merged in (.+) \(pull request #[0-9]+\)$").unwrap(),
            ],
        }
    }
}

/// Character indices into a character set.
pub mod chars {
    pub const SPACE: u8 = 0;
    pub const DOT: u8 = 1;
    pub const CIRCLE: u8 = 2;
    pub const VER: u8 = 3;
    pub const HOR: u8 = 4;
    pub const CROSS: u8 = 5;
    pub const R_U: u8 = 6;
    pub const R_D: u8 = 7;
    pub const L_D: u8 = 8;
    pub const L_U: u8 = 9;
    pub const VER_L: u8 = 10;
    pub const VER_R: u8 = 11;
    pub const HOR_U: u8 = 12;
    pub const HOR_D: u8 = 13;
    pub const ARR_L: u8 = 14;
    pub const ARR_R: u8 = 15;
}

pub struct Characters {
    pub chars: Vec<char>,
}

impl Characters {
    fn of(s: &str) -> Characters {
        Characters {
            chars: s.chars().collect(),
        }
    }

    pub fn from_name(name: &str) -> Result<Characters, String> {
        match name {
            "normal" | "thin" | "n" | "t" => Ok(Characters::of(" ●○│─┼└┌┐┘┤├┴┬<>")),
            "round" | "r" => Ok(Characters::of(" ●○│─┼╰╭╮╯┤├┴┬<>")),
            "bold" | "b" => Ok(Characters::of(" ●○┃━╋┗┏┓┛┫┣┻┳<>")),
            "double" | "d" => Ok(Characters::of(" ●○║═╬╚╔╗╝╣╠╩╦<>")),
            "ascii" | "a" => Ok(Characters::of(" *o|-+'..'||++<>")),
            _ => Err(format!(
                "Unknown characters/style '{}'. Must be one of [normal|thin|round|bold|double|ascii]",
                name
            )),
        }
    }

    pub fn thin() -> Characters {
        Characters::of(" ●○│─┼└┌┐┘┤├┴┬<>")
    }
}

#[derive(Clone, PartialEq, Eq)]
pub enum CommitFormat {
    OneLine,
    Short,
    Medium,
    Full,
    Format(String),
}

impl CommitFormat {
    pub fn parse(s: &str) -> CommitFormat {
        match s {
            "oneline" | "o" => CommitFormat::OneLine,
            "short" | "s" => CommitFormat::Short,
            "medium" | "m" => CommitFormat::Medium,
            "full" | "f" => CommitFormat::Full,
            other => CommitFormat::Format(other.to_string()),
        }
    }
}

