pub struct Settings {
    pub reverse_commit_order: bool,
    pub debug: bool,
    pub colored: bool,
    pub compact: bool,
    pub include_remote: bool,
    pub format: CommitFormat,
    pub wrapping: Wrapping,
    pub characters: Characters,
    pub model: Model,
    pub merge_patterns: MergePatterns,
}
EOF"}

