//! Handling of the application's model directory and repository configuration.

use crate::settings::{ModelDef, RepoSettings, GIT_FLOW_TOML, NONE_TOML, SIMPLE_TOML};
use git2::Repository;
use std::path::{Path, PathBuf};

pub const REPO_CONFIG_FILE: &str = "git-graph.toml";

/// Returns the directory where branching models are stored.
pub fn models_dir() -> Option<PathBuf> {
    dirs::config_dir().map(|mut p| {
        p.push("git-graph");
        p.push("models");
        p
    })
}

/// Creates the models directory with the default models, if it does not exist.
pub fn create_config(models: &Path) -> Result<(), String> {
    if !models.exists() {
        std::fs::create_dir_all(models).map_err(|e| e.to_string())?;
        let defaults = [
            ("git-flow", GIT_FLOW_TOML),
            ("simple", SIMPLE_TOML),
            ("none", NONE_TOML),
        ];
        for (name, content) in defaults.iter() {
            let mut path = PathBuf::from(models);
            path.push(format!("{}.toml", name));
            std::fs::write(&path, content).map_err(|e| e.to_string())?;
        }
    }
    Ok(())
}

/// Lists the names of all models found in the models directory.
pub fn available_models(models: &Path) -> Result<Vec<String>, String> {
