//! Construction of the commit graph: branch identification, tracing and
//! column assignment.

use crate::settings::{Model, Settings};
use git2::{BranchType, Oid, Repository};
use regex::Regex;
use std::collections::{HashMap, HashSet};

const ORIGIN: &str = "origin/";
const FORK: &str = "fork/";

pub struct CommitInfo {
    pub oid: Oid,
    pub is_merge: bool,
    pub parents: [Option<Oid>; 2],
    pub children: Vec<Oid>,
    pub branches: Vec<usize>,
    pub tags: Vec<usize>,
    pub branch_trace: Option<usize>,
}

pub struct BranchVis {
    pub order_group: usize,
    pub target_order_group: Option<usize>,
    pub source_order_group: Option<usize>,
    pub term_color: u8,
    pub svg_color: String,
    pub column: Option<usize>,
}

pub struct BranchInfo {
    pub target: Oid,
    pub merge_target: Option<Oid>,
    pub source_branch: Option<usize>,
    pub target_branch: Option<usize>,
    pub name: String,
    pub persistence: u8,
    pub is_remote: bool,
    pub is_merged: bool,
    pub is_tag: bool,
    pub visual: BranchVis,
    pub range: (Option<usize>, Option<usize>),
}

pub struct HeadInfo {
    pub oid: Oid,
    pub name: String,
    pub is_branch: bool,
}

pub struct GitGraph {
    pub repository: Repository,
    pub commits: Vec<CommitInfo>,
    pub indices: HashMap<Oid, usize>,
    pub all_branches: Vec<BranchInfo>,
    pub head: HeadInfo,
}

fn gerr(e: git2::Error) -> String {
    e.message().to_string()
}

impl GitGraph {
    pub fn new(
        mut repository: Repository,
        settings: &Settings,
        max_count: Option<usize>,
    ) -> Result<GitGraph, String> {
        let mut stashes = HashSet::new();
        repository
            .stash_foreach(|_, _, oid| {
                stashes.insert(*oid);
                true
            })
            .map_err(gerr)?;

        let mut walk = repository.revwalk().map_err(gerr)?;
        walk.set_sorting(git2::Sort::TOPOLOGICAL | git2::Sort::TIME)
            .map_err(gerr)?;
        walk.push_glob("*").map_err(gerr)?;

        if repository.is_shallow() {
            return Err("ERROR: git-graph does not support shallow clones due to a missing feature in the underlying libgit2 library.".to_string());
        }

        let head = {
            let head_ref = repository.head().map_err(gerr)?;
            head_info(&head_ref).map_err(gerr)?
        };

        let mut commits: Vec<CommitInfo> = Vec::new();
        let mut indices: HashMap<Oid, usize> = HashMap::new();
        for oid in walk {
            if let Some(max) = max_count {
                if commits.len() >= max {
                    break;
                }
            }
            if let Ok(oid) = oid {
                if stashes.contains(&oid) {
                    continue;
                }
                let commit = repository.find_commit(oid).map_err(gerr)?;
                let parents = [commit.parent_id(0).ok(), commit.parent_id(1).ok()];
                indices.insert(oid, commits.len());
                commits.push(CommitInfo {
                    oid,
                    is_merge: commit.parent_count() > 1,
                    parents,
                    children: Vec::new(),
                    branches: Vec::new(),
                    tags: Vec::new(),
                    branch_trace: None,
                });
            }
        }
        drop(walk);

        // children
        for idx in 0..commits.len() {
            let oid = commits[idx].oid;
            let parents = commits[idx].parents;
            for par in parents.iter().flatten() {
                if let Some(&pi) = indices.get(par) {
                    commits[pi].children.push(oid);
                }
            }
        }

        let mut branches = assign_branches(&repository, &mut commits, &indices, settings)?;
        correct_fork_merges(&commits, &indices, &mut branches, &settings.model)?;
        assign_sources_targets(&commits, &indices, &mut branches);
        assign_branch_columns(&commits, &indices, &mut branches, &settings.model, true, true);

        let filtered: Vec<CommitInfo> = commits
            .into_iter()
            .filter(|c| c.branch_trace.is_some())
            .collect();
        let filtered_indices: HashMap<Oid, usize> = filtered
            .iter()
            .enumerate()
            .map(|(i, c)| (c.oid, i))
            .collect();
        let index_map: HashMap<usize, Option<usize>> = indices
            .iter()
            .map(|(oid, idx)| (*idx, filtered_indices.get(oid).cloned()))
            .collect();

        for branch in branches.iter_mut() {
            if let Some(mut start) = branch.range.0 {
                let mut mapped = index_map[&start];
                while mapped.is_none() {
                    start += 1;
                    mapped = index_map[&start];
                }
                branch.range.0 = mapped;
            }
            if let Some(mut end) = branch.range.1 {
                let mut mapped = index_map[&end];
                while mapped.is_none() {
                    end -= 1;
                    mapped = index_map[&end];
                }
                branch.range.1 = mapped;
            }
        }

        Ok(GitGraph {
            repository,
            commits: filtered,
            indices: filtered_indices,
            all_branches: branches,
            head,
        })
    }
}

fn head_info(r: &git2::Reference) -> Result<HeadInfo, git2::Error> {
    let name = r
        .name()
        .ok_or_else(|| git2::Error::from_str("No name for HEAD"))?
        .to_string();
    let oid = r
        .target()
        .ok_or_else(|| git2::Error::from_str("No id for HEAD"))?;
    if name == "HEAD" {
        Ok(HeadInfo {
            oid,
            name,
            is_branch: false,
        })
    } else {
        Ok(HeadInfo {
            oid,
            name: name[11..].to_string(),
            is_branch: true,
        })
    }
}

/// Converts a color name or 256-color index to a terminal color code.
pub fn to_terminal_color(color: &str) -> Result<u8, String> {
    let code = match color {
        "black" => 0,
        "red" => 1,
        "green" => 2,
        "yellow" => 3,
        "blue" => 4,
        "magenta" => 5,
        "cyan" => 6,
        "white" => 7,
        "bright_black" => 8,
        "bright_red" => 9,
        "bright_green" => 10,
        "bright_yellow" => 11,
        "bright_blue" => 12,
        "bright_magenta" => 13,
        "bright_cyan" => 14,
        "bright_white" => 15,
        other => match other.parse::<u8>() {
            Ok(c) => c,
            Err(_) => return Err(format!("Color {} not found", other)),
        },
    };
    Ok(code)
}

fn branch_color(name: &str, matches: &[(Regex, Vec<String>)], unknown: &[String], counter: usize) -> String {
    for (re, colors) in matches {
        if re.is_match(name) {
            return colors[counter % colors.len()].clone();
        }
    }
    unknown[counter % unknown.len()].clone()
}

fn branch_order(name: &str, patterns: &[Regex]) -> usize {
    patterns
        .iter()
        .position(|re| (name.starts_with(ORIGIN) && re.is_match(&name[7..])) || re.is_match(name))
        .unwrap_or(patterns.len())
}

fn parse_merge_summary(summary: &str, patterns: &[Regex]) -> Option<String> {
    for re in patterns {
        if let Some(caps) = re.captures(summary) {
            if caps.len() == 2 {
                if let Some(m) = caps.get(1) {
                    return Some(m.as_str().to_string());
                }
            }
        }
    }
    None
}

#[allow(clippy::too_many_arguments)]
fn new_branch(
    target: Oid,
    merge_target: Option<Oid>,
    name: String,
    persistence: u8,
    is_remote: bool,
    is_merged: bool,
    is_tag: bool,
    order_group: usize,
    term_color: u8,
    svg_color: String,
    end_index: Option<usize>,
) -> BranchInfo {
    BranchInfo {
        target,
        merge_target,
        source_branch: None,
        target_branch: None,
        name,
        persistence,
        is_remote,
        is_merged,
        is_tag,
        visual: BranchVis {
            order_group,
            target_order_group: None,
            source_order_group: None,
            term_color,
            svg_color,
            column: None,
        },
        range: (end_index, None),
    }
}

fn extract_branches(
    repository: &Repository,
    commits: &[CommitInfo],
    indices: &HashMap<Oid, usize>,
    settings: &Settings,
) -> Result<Vec<BranchInfo>, String> {
    let model = &settings.model;
    let filter = if settings.include_remote {
        None
    } else {
        Some(BranchType::Local)
    };
    let actual = repository
        .branches(filter)
        .map_err(gerr)?
        .collect::<Result<Vec<_>, git2::Error>>()
        .map_err(gerr)?;

    let mut counter = 0usize;
    let mut result = Vec::new();
    for (branch, tp) in actual.iter() {
        let reference = branch.get();
        let full_name = match reference.name() {
            Some(n) => n,
            None => continue,
        };
        let target = match reference.target() {
            Some(t) => t,
            None => continue,
        };
        counter += 1;
        let start = match tp {
            BranchType::Local => 11,
            BranchType::Remote => 13,
        };
        let name = &full_name[start..];
        let end_index = indices.get(&target).cloned();
        let term_color = to_terminal_color(&branch_color(
            name,
            &model.terminal_colors,
            &model.terminal_colors_unknown,
            counter,
        ))?;
        let svg_color = branch_color(name, &model.svg_colors, &model.svg_colors_unknown, counter);
        result.push(new_branch(
            target,
            None,
            name.to_string(),
            branch_order(name, &model.persistence) as u8,
            *tp == BranchType::Remote,
            false,
            false,
            branch_order(name, &model.order),
            term_color,
            svg_color,
            end_index,
        ));
    }

    for (idx, info) in commits.iter().enumerate() {
        if !info.is_merge {
            continue;
        }
        let commit = repository.find_commit(info.oid).map_err(gerr)?;
        if let Some(summary) = commit.summary() {
            counter += 1;
            let parent_oid = commit.parent_id(1).map_err(gerr)?;
            let name = parse_merge_summary(summary, &settings.merge_patterns.patterns)
                .unwrap_or_else(|| "unknown".to_string());
            let persistence = branch_order(&name, &model.persistence) as u8;
            let pos = branch_order(&name, &model.order);
            let term_color = to_terminal_color(&branch_color(
                &name,
                &model.terminal_colors,
                &model.terminal_colors_unknown,
                counter,
            ))?;
            let svg_color = branch_color(&name, &model.svg_colors, &model.svg_colors_unknown, counter);
            result.push(new_branch(
                parent_oid,
                Some(info.oid),
                name,
                persistence,
                false,
                true,
                false,
                pos,
                term_color,
                svg_color,
                Some(idx + 1),
            ));
        }
    }

    result.sort_by_cached_key(|b| (b.persistence, !b.is_merged));

    let mut tags: Vec<(Oid, Vec<u8>)> = Vec::new();
    repository
        .tag_foreach(|oid, name| {
            tags.push((oid, name.to_vec()));
            true
        })
        .map_err(gerr)?;

    for (oid, name) in tags {
        let name = std::str::from_utf8(&name[5..]).map_err(|e| e.to_string())?;
        let target = repository
            .find_tag(oid)
            .map(|t| t.target_id())
            .or_else(|_| repository.find_commit(oid).map(|_| oid));
        if let Ok(target_oid) = target {
            if let Some(&target_index) = indices.get(&target_oid) {
                counter += 1;
                let term_color = to_terminal_color(&branch_color(
                    name,
                    &model.terminal_colors,
                    &model.terminal_colors_unknown,
                    counter,
                ))?;
                let pos = branch_order(name, &model.order);
                let svg_color = branch_color(name, &model.svg_colors, &model.svg_colors_unknown, counter);
                result.push(new_branch(
                    target_oid,
                    None,
                    name.to_string(),
                    model.persistence.len() as u8 + 1,
                    false,
                    false,
                    true,
                    pos,
                    term_color,
                    svg_color,
                    Some(target_index),
                ));
            }
        }
    }

    Ok(result)
}

fn assign_branches(
    repository: &Repository,
    commits: &mut [CommitInfo],
    indices: &HashMap<Oid, usize>,
    settings: &Settings,
) -> Result<Vec<BranchInfo>, String> {
    let mut branches = extract_branches(repository, commits, indices, settings)?;

    let mut next = 0usize;
    let mut index_map: Vec<Option<usize>> = Vec::with_capacity(branches.len());
    for old_idx in 0..branches.len() {
        let target = branches[old_idx].target;
        let is_tag = branches[old_idx].is_tag;
        let is_merged = branches[old_idx].is_merged;
        if let Some(&idx) = indices.get(&target) {
            if is_tag {
                commits[idx].tags.push(old_idx);
            } else if !is_merged {
                commits[idx].branches.push(old_idx);
            }
            let oid = commits[idx].oid;
            let any_assigned = trace_branch(commits, indices, &mut branches, oid, old_idx);
            if any_assigned || !is_merged {
                index_map.push(Some(next));
                next += 1;
            } else {
                index_map.push(None);
            }
        } else {
            index_map.push(None);
        }
    }

    let mut commit_count = vec![0usize; branches.len()];
    for info in commits.iter() {
        if let Some(t) = info.branch_trace {
            commit_count[t] += 1;
        }
    }

    let mut skipped = 0usize;
    for (idx, branch) in branches.iter().enumerate() {
        if let Some(mapped) = index_map[idx] {
            if commit_count[idx] == 0 && branch.is_merged && !branch.is_tag {
                index_map[idx] = None;
                skipped += 1;
            } else {
                index_map[idx] = Some(mapped - skipped);
            }
        }
    }

    for info in commits.iter_mut() {
        if let Some(t) = info.branch_trace {
            info.branch_trace = index_map[t];
            for b in info.branches.iter_mut() {
                *b = index_map[*b].unwrap();
            }
            for t in info.tags.iter_mut() {
                *t = index_map[*t].unwrap();
            }
        }
    }

    let result = branches
        .into_iter()
        .enumerate()
        .filter_map(|(i, b)| if index_map[i].is_some() { Some(b) } else { None })
        .collect();
    Ok(result)
}

fn trace_branch(
    commits: &mut [CommitInfo],
    indices: &HashMap<Oid, usize>,
    branches: &mut [BranchInfo],
    oid: Oid,
    branch_index: usize,
) -> bool {
    let mut curr = oid;
    let mut prev_index: Option<usize> = None;
    let mut start_index: Option<i64> = None;
    let mut any_assigned = false;

    while let Some(&index) = indices.get(&curr) {
        if let Some(old_trace) = commits[index].branch_trace {
            let old_name = branches[old_trace].name.clone();
            let old_term = branches[old_trace].visual.term_color;
            let old_svg = branches[old_trace].visual.svg_color.clone();
            let old_range = branches[old_trace].range;
            let old_end = old_range.0.unwrap_or(0);
            let new_end = branches[branch_index].range.0.unwrap_or(0);
            if branches[branch_index].name == old_name && old_end >= new_end {
                let old_branch = &mut branches[old_trace];
                match old_range.1 {
                    Some(old_start) if index > old_start => {
                        old_branch.range = (None, None);
                    }
                    _ => {
                        old_branch.range = (Some(index), old_branch.range.1);
                    }
                }
            } else {
                let branch = &mut branches[branch_index];
                if branch.name.starts_with(ORIGIN) && branch.name[7..] == old_name[..] {
                    branch.visual.term_color = old_term;
                    branch.visual.svg_color = old_svg;
                }
                match prev_index {
                    None => start_index = Some(index as i64 - 1),
                    Some(prev) => {
                        if commits[prev].is_merge {
                            let mut temp = prev;
                            for sibling in commits[index].children.iter() {
                                if sibling != &curr {
                                    let si = indices[sibling];
                                    if si > temp {
                                        temp = si;
                                    }
                                }
                            }
                            start_index = Some(temp as i64);
                        } else {
                            start_index = Some(index as i64 - 1);
                        }
                    }
                }
                break;
            }
        }

        commits[index].branch_trace = Some(branch_index);
        any_assigned = true;

        match commits[index].parents[0] {
            None => {
                start_index = Some(index as i64);
                break;
            }
            Some(p) => {
                prev_index = Some(index);
                curr = p;
            }
        }
    }

    let branch = &mut branches[branch_index];
    if let Some(end) = branch.range.0 {
        if let Some(si) = start_index {
            if si < end as i64 {
                branch.range = (None, None);
            } else {
                branch.range = (branch.range.0, Some(si as usize));
            }
        } else {
            branch.range = (branch.range.0, None);
        }
    } else {
        branch.range = (branch.range.0, start_index.map(|s| s as usize));
    }
    any_assigned
}

fn correct_fork_merges(
    commits: &[CommitInfo],
    indices: &HashMap<Oid, usize>,
    branches: &mut [BranchInfo],
    model: &Model,
) -> Result<(), String> {
    for idx in 0..branches.len() {
        let target_trace = branches[idx]
            .merge_target
            .and_then(|oid| indices.get(&oid))
            .and_then(|i| commits.get(*i))
            .and_then(|info| info.branch_trace);
        if let Some(trace) = target_trace {
            if trace < branches.len() && branches[idx].name == branches[trace].name {
                let name = format!("{}{}", FORK, branches[idx].name);
                let term_color = to_terminal_color(&branch_color(
                    &name,
                    &model.terminal_colors,
                    &model.terminal_colors_unknown,
                    idx,
                ))?;
                let pos = branch_order(&name, &model.order);
                let svg_color = branch_color(&name, &model.svg_colors, &model.svg_colors_unknown, idx);
                let b = &mut branches[idx];
                b.name = name;
                b.visual.order_group = pos;
                b.visual.term_color = term_color;
                b.visual.svg_color = svg_color;
            }
        }
    }
    Ok(())
}

fn assign_sources_targets(commits: &[CommitInfo], indices: &HashMap<Oid, usize>, branches: &mut [BranchInfo]) {
    for idx in 0..branches.len() {
        let target_branch = branches[idx]
            .merge_target
            .and_then(|oid| indices.get(&oid))
            .and_then(|i| commits.get(*i))
            .and_then(|info| info.branch_trace);
        branches[idx].target_branch = target_branch;
        let group = target_branch
            .and_then(|t| branches.get(t))
            .map(|b| b.visual.order_group);
        branches[idx].visual.target_order_group = group;
    }

    for info in commits.iter() {
        let mut max_par_order: Option<usize> = None;
        let mut source_branch: Option<usize> = None;
        for par in info.parents.iter() {
            let par_info = par
                .and_then(|oid| indices.get(&oid))
                .and_then(|i| commits.get(*i));
            if let Some(par_info) = par_info {
                if par_info.branch_trace != info.branch_trace {
                    if let Some(t) = par_info.branch_trace {
                        source_branch = Some(t);
                    }
                    let group = par_info
                        .branch_trace
                        .and_then(|t| branches.get(t))
                        .map(|b| b.visual.order_group);
                    match max_par_order {
                        Some(gr) => {
                            if let Some(pg) = group {
                                if pg > gr {
                                    max_par_order = group;
                                }
                            }
                        }
                        None => max_par_order = group,
                    }
                }
            }
        }
        if let Some(branch) = info.branch_trace.and_then(|t| branches.get_mut(t)) {
            if let Some(order) = max_par_order {
                branch.visual.source_order_group = Some(order);
            }
            if let Some(src) = source_branch {
                branch.source_branch = Some(src);
            }
        }
    }
}

fn assign_branch_columns(
    commits: &[CommitInfo],
    indices: &HashMap<Oid, usize>,
    branches: &mut [BranchInfo],
    model: &Model,
    shortest_first: bool,
    forward: bool,
) {
    let num_groups = model.order.len() + 1;
    let mut occupied: Vec<Vec<Vec<(usize, usize)>>> = vec![vec![]; num_groups];

    let length_factor: i64 = if shortest_first { 1 } else { -1 };
    let start_factor: i64 = if forward { 1 } else { -1 };

    let num_branches = branches.len();
    let mut sorted: Vec<(usize, usize, usize, usize, usize)> = branches
        .iter()
        .enumerate()
        .filter(|(_, b)| b.range.0.is_some() || b.range.1.is_some())
        .map(|(i, b)| {
            (
                i,
                b.range.0.unwrap_or(0),
                b.range.1.unwrap_or(num_branches - 1),
                b.visual.source_order_group.unwrap_or(model.order.len() + 1),
                b.visual.target_order_group.unwrap_or(model.order.len() + 1),
            )
        })
        .collect();

    sorted.sort_by_cached_key(|t| {
        (
            std::cmp::max(t.3, t.4),
            (t.2 as i64 - t.1 as i64) * length_factor,
            t.1 as i64 * start_factor,
        )
    });

    for (branch_idx, start, end, _, _) in sorted {
        let group = branches[branch_idx].visual.order_group;
        let align_right = branches[branch_idx]
            .source_branch
            .map(|s| branches[s].visual.order_group > group)
            .unwrap_or(false)
            || branches[branch_idx]
                .target_branch
                .map(|t| branches[t].visual.order_group > group)
                .unwrap_or(false);

        let merge_column = branches[branch_idx]
            .merge_target
            .and_then(|t| indices.get(&t))
            .and_then(|ti| commits[*ti].branch_trace)
            .and_then(|mt| {
                let mb = &branches[mt];
                if mb.visual.order_group == group {
                    mb.visual.column
                } else {
                    None
                }
            });

        let group_occ = &mut occupied[group];
        let len = group_occ.len();
        let mut found = len;
        for i in 0..len {
            let index = if align_right { len - i - 1 } else { i };
            let mut occ = group_occ[index]
                .iter()
                .any(|(s, e)| start <= *e && end >= *s);
            if !occ {
                if let Some(mc) = merge_column {
                    if mc == index {
                        occ = true;
                    }
                }
            }
            if !occ {
                found = index;
                break;
            }
        }

        branches[branch_idx].visual.column = Some(found);
        if found == group_occ.len() {
            group_occ.push(vec![]);
        }
        group_occ[found].push((start, end));
    }

    let mut offsets = Vec::with_capacity(occupied.len());
    let mut acc = 0;
    for g in occupied.iter() {
        acc += g.len();
        offsets.push(acc);
    }

    for branch in branches.iter_mut() {
        if let Some(col) = branch.visual.column {
            let offset = if branch.visual.order_group == 0 {
                0
            } else {
                offsets[branch.visual.order_group - 1]
            };
            branch.visual.column = Some(col + offset);
        }
    }
}
EOF"}

actions.command:
cd /workspace && cat > src/graph.rs <<'EOF'
//! Construction of the commit graph: branch identification, tracing and
//! column assignment.

use crate::settings::{Model, Settings};
use git2::{BranchType, Oid, Repository};
use regex::Regex;
use std::collections::{HashMap, HashSet};

const ORIGIN: &str = "origin/";
const FORK: &str = "fork/";

pub struct CommitInfo {
    pub oid: Oid,
    pub is_merge: bool,
    pub parents: [Option<Oid>; 2],
    pub children: Vec<Oid>,
    pub branches: Vec<usize>,
    pub tags: Vec<usize>,
    pub branch_trace: Option<usize>,
}

pub struct BranchVis {
    pub order_group: usize,
    pub target_order_group: Option<usize>,
    pub source_order_group: Option<usize>,
    pub term_color: u8,
    pub svg_color: String,
    pub column: Option<usize>,
}

pub struct BranchInfo {
    pub target: Oid,
    pub merge_target: Option<Oid>,
    pub source_branch: Option<usize>,
    pub target_branch: Option<usize>,
    pub name: String,
    pub persistence: u8,
    pub is_remote: bool,
    pub is_merged: bool,
    pub is_tag: bool,
    pub visual: BranchVis,
    pub range: (Option<usize>, Option<usize>),
}

pub struct HeadInfo {
    pub oid: Oid,
    pub name: String,
    pub is_branch: bool,
}

pub struct GitGraph {
    pub repository: Repository,
    pub commits: Vec<CommitInfo>,
    pub indices: HashMap<Oid, usize>,
    pub all_branches: Vec<BranchInfo>,
    pub head: HeadInfo,
}

fn gerr(e: git2::Error) -> String {
    e.message().to_string()
}

impl GitGraph {
    pub fn new(
        mut repository: Repository,
        settings: &Settings,
        max_count: Option<usize>,
    ) -> Result<GitGraph, String> {
        let mut stashes = HashSet::new();
        repository
            .stash_foreach(|_, _, oid| {
                stashes.insert(*oid);
                true
            })
            .map_err(gerr)?;

        let mut walk = repository.revwalk().map_err(gerr)?;
        walk.set_sorting(git2::Sort::TOPOLOGICAL | git2::Sort::TIME)
            .map_err(gerr)?;
        walk.push_glob("*").map_err(gerr)?;

        if repository.is_shallow() {
            return Err("ERROR: git-graph does not support shallow clones due to a missing feature in the underlying libgit2 library.".to_string());
        }

        let head = {
            let head_ref = repository.head().map_err(gerr)?;
            head_info(&head_ref).map_err(gerr)?
        };

        let mut commits: Vec<CommitInfo> = Vec::new();
        let mut indices: HashMap<Oid, usize> = HashMap::new();
        for oid in walk {
            if let Some(max) = max_count {
                if commits.len() >= max {
                    break;
                }
            }
            if let Ok(oid) = oid {
                if stashes.contains(&oid) {
                    continue;
                }
                let commit = repository.find_commit(oid).map_err(gerr)?;
                let parents = [commit.parent_id(0).ok(), commit.parent_id(1).ok()];
                indices.insert(oid, commits.len());
                commits.push(CommitInfo {
                    oid,
                    is_merge: commit.parent_count() > 1,
                    parents,
                    children: Vec::new(),
                    branches: Vec::new(),
                    tags: Vec::new(),
                    branch_trace: None,
                });
            }
        }
        drop(walk);

        // children
        for idx in 0..commits.len() {
            let oid = commits[idx].oid;
            let parents = commits[idx].parents;
            for par in parents.iter().flatten() {
                if let Some(&pi) = indices.get(par) {
                    commits[pi].children.push(oid);
                }
            }
        }

        let mut branches = assign_branches(&repository, &mut commits, &indices, settings)?;
        correct_fork_merges(&commits, &indices, &mut branches, &settings.model)?;
        assign_sources_targets(&commits, &indices, &mut branches);
        assign_branch_columns(&commits, &indices, &mut branches, &settings.model, true, true);

        let filtered: Vec<CommitInfo> = commits
            .into_iter()
            .filter(|c| c.branch_trace.is_some())
            .collect();
        let filtered_indices: HashMap<Oid, usize> = filtered
            .iter()
            .enumerate()
            .map(|(i, c)| (c.oid, i))
            .collect();
        let index_map: HashMap<usize, Option<usize>> = indices
            .iter()
            .map(|(oid, idx)| (*idx, filtered_indices.get(oid).cloned()))
            .collect();

        for branch in branches.iter_mut() {
            if let Some(mut start) = branch.range.0 {
                let mut mapped = index_map[&start];
                while mapped.is_none() {
                    start += 1;
                    mapped = index_map[&start];
                }
                branch.range.0 = mapped;
            }
            if let Some(mut end) = branch.range.1 {
                let mut mapped = index_map[&end];
                while mapped.is_none() {
                    end -= 1;
                    mapped = index_map[&end];
                }
                branch.range.1 = mapped;
            }
        }

        Ok(GitGraph {
            repository,
            commits: filtered,
            indices: filtered_indices,
            all_branches: branches,
            head,
        })
    }
}

fn head_info(r: &git2::Reference) -> Result<HeadInfo, git2::Error> {
    let name = r
        .name()
        .ok_or_else(|| git2::Error::from_str("No name for HEAD"))?
        .to_string();
    let oid = r
        .target()
        .ok_or_else(|| git2::Error::from_str("No id for HEAD"))?;
    if name == "HEAD" {
        Ok(HeadInfo {
            oid,
            name,
            is_branch: false,
        })
    } else {
        Ok(HeadInfo {
            oid,
            name: name[11..].to_string(),
            is_branch: true,
        })
    }
}

/// Converts a color name or 256-color index to a terminal color code.
pub fn to_terminal_color(color: &str) -> Result<u8, String> {
    let code = match color {
        "black" => 0,
        "red" => 1,
        "green" => 2,
        "yellow" => 3,
        "blue" => 4,
        "magenta" => 5,
        "cyan" => 6,
        "white" => 7,
        "bright_black" => 8,
        "bright_red" => 9,
        "bright_green" => 10,
        "bright_yellow" => 11,
        "bright_blue" => 12,
        "bright_magenta" => 13,
        "bright_cyan" => 14,
        "bright_white" => 15,
        other => match other.parse::<u8>() {
            Ok(c) => c,
            Err(_) => return Err(format!("Color {} not found", other)),
        },
    };
    Ok(code)
}

fn branch_color(name: &str, matches: &[(Regex, Vec<String>)], unknown: &[String], counter: usize) -> String {
    for (re, colors) in matches {
        if re.is_match(name) {
            return colors[counter % colors.len()].clone();
        }
    }
    unknown[counter % unknown.len()].clone()
}

fn branch_order(name: &str, patterns: &[Regex]) -> usize {
    patterns
        .iter()
        .position(|re| (name.starts_with(ORIGIN) && re.is_match(&name[7..])) || re.is_match(name))
        .unwrap_or(patterns.len())
}

fn parse_merge_summary(summary: &str, patterns: &[Regex]) -> Option<String> {
    for re in patterns {
        if let Some(caps) = re.captures(summary) {
            if caps.len() == 2 {
                if let Some(m) = caps.get(1) {
                    return Some(m.as_str().to_string());
                }
            }
        }
    }
    None
}

#[allow(clippy::too_many_arguments)]
fn new_branch(
    target: Oid,
    merge_target: Option<Oid>,
    name: String,
    persistence: u8,
    is_remote: bool,
    is_merged: bool,
    is_tag: bool,
    order_group: usize,
    term_color: u8,
    svg_color: String,
    end_index: Option<usize>,
) -> BranchInfo {
    BranchInfo {
        target,
        merge_target,
        source_branch: None,
        target_branch: None,
        name,
        persistence,
        is_remote,
        is_merged,
        is_tag,
        visual: BranchVis {
            order_group,
            target_order_group: None,
            source_order_group: None,
            term_color,
            svg_color,
            column: None,
        },
        range: (end_index, None),
    }
}

fn extract_branches(
    repository: &Repository,
    commits: &[CommitInfo],
    indices: &HashMap<Oid, usize>,
    settings: &Settings,
) -> Result<Vec<BranchInfo>, String> {
    let model = &settings.model;
    let filter = if settings.include_remote {
        None
    } else {
        Some(BranchType::Local)
    };
    let actual = repository
        .branches(filter)
        .map_err(gerr)?
        .collect::<Result<Vec<_>, git2::Error>>()
        .map_err(gerr)?;

    let mut counter = 0usize;
    let mut result = Vec::new();
    for (branch, tp) in actual.iter() {
        let reference = branch.get();
        let full_name = match reference.name() {
            Some(n) => n,
            None => continue,
        };
        let target = match reference.target() {
            Some(t) => t,
            None => continue,
        };
        counter += 1;
        let start = match tp {
            BranchType::Local => 11,
            BranchType::Remote => 13,
        };
        let name = &full_name[start..];
        let end_index = indices.get(&target).cloned();
        let term_color = to_terminal_color(&branch_color(
            name,
            &model.terminal_colors,
            &model.terminal_colors_unknown,
            counter,
        ))?;
        let svg_color = branch_color(name, &model.svg_colors, &model.svg_colors_unknown, counter);
        result.push(new_branch(
            target,
            None,
            name.to_string(),
            branch_order(name, &model.persistence) as u8,
            *tp == BranchType::Remote,
            false,
            false,
            branch_order(name, &model.order),
            term_color,
            svg_color,
            end_index,
        ));
    }

    for (idx, info) in commits.iter().enumerate() {
        if !info.is_merge {
            continue;
        }
        let commit = repository.find_commit(info.oid).map_err(gerr)?;
        if let Some(summary) = commit.summary() {
            counter += 1;
            let parent_oid = commit.parent_id(1).map_err(gerr)?;
            let name = parse_merge_summary(summary, &settings.merge_patterns.patterns)
                .unwrap_or_else(|| "unknown".to_string());
            let persistence = branch_order(&name, &model.persistence) as u8;
            let pos = branch_order(&name, &model.order);
            let term_color = to_terminal_color(&branch_color(
                &name,
                &model.terminal_colors,
                &model.terminal_colors_unknown,
                counter,
            ))?;
            let svg_color = branch_color(&name, &model.svg_colors, &model.svg_colors_unknown, counter);
            result.push(new_branch(
                parent_oid,
                Some(info.oid),
                name,
                persistence,
                false,
                true,
                false,
                pos,
                term_color,
                svg_color,
                Some(idx + 1),
            ));
        }
    }

    result.sort_by_cached_key(|b| (b.persistence, !b.is_merged));

    let mut tags: Vec<(Oid, Vec<u8>)> = Vec::new();
    repository
        .tag_foreach(|oid, name| {
            tags.push((oid, name.to_vec()));
            true
        })
        .map_err(gerr)?;

    for (oid, name) in tags {
        let name = std::str::from_utf8(&name[5..]).map_err(|e| e.to_string())?;
        let target = repository
            .find_tag(oid)
            .map(|t| t.target_id())
            .or_else(|_| repository.find_commit(oid).map(|_| oid));
        if let Ok(target_oid) = target {
            if let Some(&target_index) = indices.get(&target_oid) {
                counter += 1;
                let term_color = to_terminal_color(&branch_color(
                    name,
                    &model.terminal_colors,
                    &model.terminal_colors_unknown,
                    counter,
                ))?;
                let pos = branch_order(name, &model.order);
                let svg_color = branch_color(name, &model.svg_colors, &model.svg_colors_unknown, counter);
                result.push(new_branch(
                    target_oid,
                    None,
                    name.to_string(),
                    model.persistence.len() as u8 + 1,
                    false,
                    false,
                    true,
                    pos,
                    term_color,
                    svg_color,
                    Some(target_index),
                ));
            }
        }
    }

    Ok(result)
}

fn assign_branches(
    repository: &Repository,
    commits: &mut [CommitInfo],
    indices: &HashMap<Oid, usize>,
    settings: &Settings,
) -> Result<Vec<BranchInfo>, String> {
    let mut branches = extract_branches(repository, commits, indices, settings)?;

    let mut next = 0usize;
    let mut index_map: Vec<Option<usize>> = Vec::with_capacity(branches.len());
    for old_idx in 0..branches.len() {
        let target = branches[old_idx].target;
        let is_tag = branches[old_idx].is_tag;
        let is_merged = branches[old_idx].is_merged;
        if let Some(&idx) = indices.get(&target) {
            if is_tag {
                commits[idx].tags.push(old_idx);
            } else if !is_merged {
                commits[idx].branches.push(old_idx);
            }
            let oid = commits[idx].oid;
            let any_assigned = trace_branch(commits, indices, &mut branches, oid, old_idx);
            if any_assigned || !is_merged {
                index_map.push(Some(next));
                next += 1;
            } else {
                index_map.push(None);
            }
        } else {
            index_map.push(None);
        }
    }

    let mut commit_count = vec![0usize; branches.len()];
    for info in commits.iter() {
        if let Some(t) = info.branch_trace {
            commit_count[t] += 1;
        }
    }

    let mut skipped = 0usize;
    for (idx, branch) in branches.iter().enumerate() {
        if let Some(mapped) = index_map[idx] {
            if commit_count[idx] == 0 && branch.is_merged && !branch.is_tag {
                index_map[idx] = None;
                skipped += 1;
            } else {
                index_map[idx] = Some(mapped - skipped);
            }
        }
    }

    for info in commits.iter_mut() {
        if let Some(t) = info.branch_trace {
            info.branch_trace = index_map[t];
            for b in info.branches.iter_mut() {
                *b = index_map[*b].unwrap();
            }
            for t in info.tags.iter_mut() {
                *t = index_map[*t].unwrap();
            }
        }
    }

    let result = branches
        .into_iter()
        .enumerate()
        .filter_map(|(i, b)| if index_map[i].is_some() { Some(b) } else { None })
        .collect();
    Ok(result)
}

fn trace_branch(
    commits: &mut [CommitInfo],
    indices: &HashMap<Oid, usize>,
    branches: &mut [BranchInfo],
    oid: Oid,
    branch_index: usize,
) -> bool {
    let mut curr = oid;
    let mut prev_index: Option<usize> = None;
    let mut start_index: Option<i64> = None;
    let mut any_assigned = false;

    while let Some(&index) = indices.get(&curr) {
        if let Some(old_trace) = commits[index].branch_trace {
            let old_name = branches[old_trace].name.clone();
            let old_term = branches[old_trace].visual.term_color;
            let old_svg = branches[old_trace].visual.svg_color.clone();
            let old_range = branches[old_trace].range;
            let old_end = old_range.0.unwrap_or(0);
            let new_end = branches[branch_index].range.0.unwrap_or(0);
            if branches[branch_index].name == old_name && old_end >= new_end {
                let old_branch = &mut branches[old_trace];
                match old_range.1 {
                    Some(old_start) if index > old_start => {
                        old_branch.range = (None, None);
                    }
                    _ => {
                        old_branch.range = (Some(index), old_branch.range.1);
                    }
                }
            } else {
                let branch = &mut branches[branch_index];
                if branch.name.starts_with(ORIGIN) && branch.name[7..] == old_name[..] {
                    branch.visual.term_color = old_term;
                    branch.visual.svg_color = old_svg;
                }
                match prev_index {
                    None => start_index = Some(index as i64 - 1),
                    Some(prev) => {
                        if commits[prev].is_merge {
                            let mut temp = prev;
                            for sibling in commits[index].children.iter() {
                                if sibling != &curr {
                                    let si = indices[sibling];
                                    if si > temp {
                                        temp = si;
                                    }
                                }
                            }
                            start_index = Some(temp as i64);
                        } else {
                            start_index = Some(index as i64 - 1);
                        }
                    }
                }
                break;
            }
        }

        commits[index].branch_trace = Some(branch_index);
        any_assigned = true;

        match commits[index].parents[0] {
            None => {
                start_index = Some(index as i64);
                break;
            }
            Some(p) => {
                prev_index = Some(index);
                curr = p;
            }
        }
    }

    let branch = &mut branches[branch_index];
    if let Some(end) = branch.range.0 {
        if let Some(si) = start_index {
            if si < end as i64 {
                branch.range = (None, None);
            } else {
                branch.range = (branch.range.0, Some(si as usize));
            }
        } else {
            branch.range = (branch.range.0, None);
        }
    } else {
        branch.range = (branch.range.0, start_index.map(|s| s as usize));
    }
    any_assigned
}

fn correct_fork_merges(
    commits: &[CommitInfo],
    indices: &HashMap<Oid, usize>,
    branches: &mut [BranchInfo],
    model: &Model,
) -> Result<(), String> {
    for idx in 0..branches.len() {
        let target_trace = branches[idx]
            .merge_target
            .and_then(|oid| indices.get(&oid))
            .and_then(|i| commits.get(*i))
            .and_then(|info| info.branch_trace);
        if let Some(trace) = target_trace {
            if trace < branches.len() && branches[idx].name == branches[trace].name {
                let name = format!("{}{}", FORK, branches[idx].name);
                let term_color = to_terminal_color(&branch_color(
                    &name,
                    &model.terminal_colors,
                    &model.terminal_colors_unknown,
                    idx,
                ))?;
                let pos = branch_order(&name, &model.order);
                let svg_color = branch_color(&name, &model.svg_colors, &model.svg_colors_unknown, idx);
                let b = &mut branches[idx];
                b.name = name;
                b.visual.order_group = pos;
                b.visual.term_color = term_color;
                b.visual.svg_color = svg_color;
            }
        }
    }
    Ok(())
}

fn assign_sources_targets(commits: &[CommitInfo], indices: &HashMap<Oid, usize>, branches: &mut [BranchInfo]) {
    for idx in 0..branches.len() {
        let target_branch = branches[idx]
            .merge_target
            .and_then(|oid| indices.get(&oid))
            .and_then(|i| commits.get(*i))
            .and_then(|info| info.branch_trace);
        branches[idx].target_branch = target_branch;
        let group = target_branch
            .and_then(|t| branches.get(t))
            .map(|b| b.visual.order_group);
        branches[idx].visual.target_order_group = group;
    }

    for info in commits.iter() {
        let mut max_par_order: Option<usize> = None;
        let mut source_branch: Option<usize> = None;
        for par in info.parents.iter() {
            let par_info = par
                .and_then(|oid| indices.get(&oid))
                .and_then(|i| commits.get(*i));
            if let Some(par_info) = par_info {
                if par_info.branch_trace != info.branch_trace {
                    if let Some(t) = par_info.branch_trace {
                        source_branch = Some(t);
                    }
                    let group = par_info
                        .branch_trace
                        .and_then(|t| branches.get(t))
                        .map(|b| b.visual.order_group);
                    match max_par_order {
                        Some(gr) => {
                            if let Some(pg) = group {
                                if pg > gr {
                                    max_par_order = group;
                                }
                            }
                        }
                        None => max_par_order = group,
                    }
                }
            }
        }
        if let Some(branch) = info.branch_trace.and_then(|t| branches.get_mut(t)) {
            if let Some(order) = max_par_order {
                branch.visual.source_order_group = Some(order);
            }
            if let Some(src) = source_branch {
                branch.source_branch = Some(src);
            }
        }
    }
}

fn assign_branch_columns(
    commits: &[CommitInfo],
    indices: &HashMap<Oid, usize>,
    branches: &mut [BranchInfo],
    model: &Model,
    shortest_first: bool,
    forward: bool,
) {
    let num_groups = model.order.len() + 1;
    let mut occupied: Vec<Vec<Vec<(usize, usize)>>> = vec![vec![]; num_groups];

    let length_factor: i64 = if shortest_first { 1 } else { -1 };
    let start_factor: i64 = if forward { 1 } else { -1 };

    let num_branches = branches.len();
    let mut sorted: Vec<(usize, usize, usize, usize, usize)> = branches
        .iter()
        .enumerate()
        .filter(|(_, b)| b.range.0.is_some() || b.range.1.is_some())
        .map(|(i, b)| {
            (
                i,
                b.range.0.unwrap_or(0),
                b.range.1.unwrap_or(num_branches - 1),
                b.visual.source_order_group.unwrap_or(model.order.len() + 1),
                b.visual.target_order_group.unwrap_or(model.order.len() + 1),
            )
        })
        .collect();

    sorted.sort_by_cached_key(|t| {
        (
            std::cmp::max(t.3, t.4),
            (t.2 as i64 - t.1 as i64) * length_factor,
            t.1 as i64 * start_factor,
        )
    });

    for (branch_idx, start, end, _, _) in sorted {
        let group = branches[branch_idx].visual.order_group;
        let align_right = branches[branch_idx]
            .source_branch
            .map(|s| branches[s].visual.order_group > group)
            .unwrap_or(false)
            || branches[branch_idx]
                .target_branch
                .map(|t| branches[t].visual.order_group > group)
                .unwrap_or(false);

        let merge_column = branches[branch_idx]
            .merge_target
            .and_then(|t| indices.get(&t))
            .and_then(|ti| commits[*ti].branch_trace)
            .and_then(|mt| {
                let mb = &branches[mt];
                if mb.visual.order_group == group {
                    mb.visual.column
                } else {
                    None
                }
            });

        let group_occ = &mut occupied[group];
        let len = group_occ.len();
        let mut found = len;
        for i in 0..len {
            let index = if align_right { len - i - 1 } else { i };
            let mut occ = group_occ[index]
                .iter()
                .any(|(s, e)| start <= *e && end >= *s);
            if !occ {
                if let Some(mc) = merge_column {
                    if mc == index {
                        occ = true;
                    }
                }
            }
            if !occ {
                found = index;
                break;
            }
        }

        branches[branch_idx].visual.column = Some(found);
        if found == group_occ.len() {
            group_occ.push(vec![]);
        }
        group_occ[found].push((start, end));
    }

    let mut offsets = Vec::with_capacity(occupied.len());
    let mut acc = 0;
    for g in occupied.iter() {
        acc += g.len();
        offsets.push(acc);
    }

    for branch in branches.iter_mut() {
        if let Some(col) = branch.visual.column {
            let offset = if branch.visual.order_group == 0 {
                0
            } else {
                offsets[branch.visual.order_group - 1]
            };
            branch.visual.column = Some(col + offset);
        }
    }
}
