//! Minimal text wrapping (first-fit, ASCII-space word separation,
//! hyphen splitting, long word breaking, ANSI-escape aware widths).

use unicode_width::UnicodeWidthChar;

#[derive(Clone)]
pub struct WrapOptions {
    pub width: usize,
    pub initial_indent: String,
    pub subsequent_indent: String,
}

impl WrapOptions {
    pub fn new(width: usize, initial_indent: &str, subsequent_indent: &str) -> Self {
        WrapOptions {
            width,
            initial_indent: initial_indent.to_string(),
            subsequent_indent: subsequent_indent.to_string(),
        }
    }
}

fn char_width(ch: char) -> usize {
    ch.width().unwrap_or(0)
}

/// Skips an ANSI CSI escape sequence. Returns true if `ch` started one.
fn skip_escape<I: Iterator<Item = char>>(ch: char, chars: &mut I) -> bool {
    if ch == '\x1b' {
        if chars.next() == Some('[') {
            for c in chars.by_ref() {
                if ('\x40'..='\x7e').contains(&c) {
                    break;
                }
            }
        }
        return true;
    }
    false
}

pub fn display_width(text: &str) -> usize {
    let mut chars = text.chars();
    let mut width = 0;
    while let Some(ch) = chars.next() {
        if skip_escape(ch, &mut chars) {
            continue;
        }
        width += char_width(ch);
    }
    width
}

#[derive(Clone, Copy, Debug)]
struct Word<'a> {
    word: &'a str,
    whitespace: &'a str,
    penalty: &'a str,
    width: usize,
}

impl<'a> Word<'a> {
    fn from(s: &'a str) -> Word<'a> {
        let trimmed = s.trim_end_matches(' ');
        Word {
            word: trimmed,
            whitespace: &s[trimmed.len()..],
            penalty: "",
            width: display_width(trimmed),
        }
    }

    fn break_apart(&self, line_width: usize) -> Vec<Word<'a>> {
        let mut result = Vec::new();
        let mut offset = 0;
        let mut width = 0;
        let word = self.word;
        let mut iter = word.char_indices().peekable();
        while let Some((idx, ch)) = iter.next() {
            if ch == '\x1b' {
                // skip escape sequence
                let mut rest = iter.clone().map(|(_, c)| c);
                let mut consumed = 0usize;
                let mut next_is_bracket = false;
                if let Some(c) = rest.next() {
                    consumed += 1;
                    if c == '[' {
                        next_is_bracket = true;
                    }
                }
                if next_is_bracket {
                    for c in rest {
                        consumed += 1;
                        if ('\x40'..='\x7e').contains(&c) {
                            break;
                        }
                    }
                }
                for _ in 0..consumed {
                    iter.next();
                }
                continue;
            }
            let cw = char_width(ch);
            if width > 0 && width + cw > line_width {
                result.push(Word {
                    word: &word[offset..idx],
                    whitespace: "",
                    penalty: "",
                    width,
                });
                offset = idx;
                width = cw;
                continue;
            }
            width += cw;
        }
        if offset < word.len() {
            result.push(Word {
                word: &word[offset..],
                whitespace: self.whitespace,
                penalty: self.penalty,
                width,
            });
        }
        result
    }
}

fn find_words(line: &str) -> Vec<Word<'_>> {
    let mut words = Vec::new();
    let mut start = 0;
    let mut in_whitespace = false;
    for (idx, ch) in line.char_indices() {
        if in_whitespace && ch != ' ' {
            words.push(Word::from(&line[start..idx]));
            start = idx;
        }
        in_whitespace = ch == ' ';
    }
    if start < line.len() {
        words.push(Word::from(&line[start..]));
    }
    words
}

fn split_points(word: &str) -> Vec<usize> {
    let mut splits = Vec::new();
    for (idx, _) in word.match_indices('-') {
        let prev = word[..idx].chars().next_back();
        let next = word[idx + 1..].chars().next();
        if prev.map(|c| c.is_alphanumeric()).unwrap_or(false)
            && next.map(|c| c.is_alphanumeric()).unwrap_or(false)
        {
            splits.push(idx + 1);
        }
    }
    splits
}

fn split_words<'a>(words: Vec<Word<'a>>) -> Vec<Word<'a>> {
    let mut result = Vec::new();
    for w in words {
        let mut prev = 0;
        for idx in split_points(w.word) {
            let need_hyphen = !w.word[..idx].ends_with('-');
            let part = &w.word[prev..idx];
            result.push(Word {
                word: part,
                whitespace: "",
                penalty: if need_hyphen { "-" } else { "" },
                width: display_width(part),
            });
            prev = idx;
        }
        if prev < w.word.len() || prev == 0 {
            let part = &w.word[prev..];
            result.push(Word {
                word: part,
                whitespace: w.whitespace,
                penalty: w.penalty,
                width: display_width(part),
            });
        }
    }
    result
}

fn break_words<'a>(words: Vec<Word<'a>>, line_width: usize) -> Vec<Word<'a>> {
    let mut result = Vec::new();
    for w in words {
        if w.width > line_width {
            result.extend(w.break_apart(line_width));
        } else {
            result.push(w);
        }
    }
    result
}

fn wrap_first_fit(words: &[Word<'_>], line_widths: &[usize]) -> Vec<(usize, usize)> {
    let default_width = *line_widths.last().unwrap_or(&0);
    let mut lines = Vec::new();
    let mut start = 0;
    let mut width = 0usize;
    for (idx, w) in words.iter().enumerate() {
        let line_width = *line_widths.get(lines.len()).unwrap_or(&default_width);
        if width + w.width + display_width(w.penalty) > line_width && idx > start {
            lines.push((start, idx));
            start = idx;
            width = 0;
        }
        width += w.width + w.whitespace.len();
    }
    lines.push((start, words.len()));
    lines
}

fn wrap_single_line(line: &str, opts: &WrapOptions, lines: &mut Vec<String>) {
    let indent = if lines.is_empty() {
        &opts.initial_indent
    } else {
        &opts.subsequent_indent
    };
    if line.len() < opts.width && indent.is_empty() {
        lines.push(line.trim_end_matches(' ').to_string());
        return;
    }

    let initial_width = opts.width.saturating_sub(display_width(&opts.initial_indent));
    let subsequent_width = opts.width.saturating_sub(display_width(&opts.subsequent_indent));
    let line_widths = [initial_width, subsequent_width];

    let words = split_words(find_words(line));
    let mut words = break_words(words, line_widths[1]);
    if !opts.initial_indent.is_empty() {
        words.insert(0, Word::from(""));
    }

    let wrapped = wrap_first_fit(&words, &line_widths);
    let mut idx = 0;
    for (s, e) in wrapped {
        let slice = &words[s..e];
        let last = match slice.last() {
            None => {
                lines.push(String::new());
                continue;
            }
            Some(w) => w,
        };
        let len = slice
            .iter()
            .map(|w| w.word.len() + w.whitespace.len())
            .sum::<usize>()
            - last.whitespace.len();
        let mut result = if lines.is_empty() && !opts.initial_indent.is_empty() {
            opts.initial_indent.clone()
        } else if !lines.is_empty() && !opts.subsequent_indent.is_empty() {
            opts.subsequent_indent.clone()
        } else {
            String::new()
        };
        result.push_str(&line[idx..idx + len]);
        if !last.penalty.is_empty() {
            result.push_str(last.penalty);
        }
        lines.push(result);
        idx += len + last.whitespace.len();
    }
}

pub fn wrap(text: &str, opts: &WrapOptions) -> Vec<String> {
    let mut lines = Vec::new();
    for line in text.split('\n') {
        wrap_single_line(line, opts, &mut lines);
    }
    lines
}

pub fn fill(text: &str, opts: &WrapOptions) -> String {
    if text.len() < opts.width && !text.contains('\n') && opts.initial_indent.is_empty() {
        text.trim_end_matches(' ').to_string()
    } else {
        wrap(text, opts).join("\n")
    }
}
