//! Formatting of commit text.

use crate::graph::{CommitInfo, GitGraph, HeadInfo};
use crate::print::colors::{paint, HEAD_COLOR};
use crate::settings::CommitFormat;
use crate::wrap::{fill, WrapOptions};
use chrono::{FixedOffset, TimeZone};
use git2::{Commit, Time};

const P_NEWLINE: usize = 0;
const P_HASH: usize = 1;
const P_HASH_ABBREV: usize = 2;
const P_PARENTS: usize = 3;
const P_PARENTS_ABBREV: usize = 4;
const P_REFS: usize = 5;
const P_SUBJECT: usize = 6;
const P_AUTHOR: usize = 7;
const P_AUTHOR_EMAIL: usize = 8;
const P_AUTHOR_DATE: usize = 9;
const P_AUTHOR_DATE_SHORT: usize = 10;
const P_AUTHOR_DATE_REL: usize = 11;
const P_COMMITTER: usize = 12;
const P_COMMITTER_EMAIL: usize = 13;
const P_COMMITTER_DATE: usize = 14;
const P_COMMITTER_DATE_SHORT: usize = 15;
const P_COMMITTER_DATE_REL: usize = 16;
const P_BODY: usize = 17;
const P_BODY_RAW: usize = 18;

const PLACEHOLDER_NAMES: [&str; 19] = [
    "n", "H", "h", "P", "p", "d", "s", "an", "ae", "ad", "as", "ar", "cn", "ce", "cd", "cs", "cr",
    "b", "B",
];

const MODE_PLAIN: usize = 0;
const MODE_SPACE: usize = 1;
const MODE_PLUS: usize = 2;
const MODE_MINUS: usize = 3;

/// Formats the branches and tags of a commit.
pub fn format_branches(graph: &GitGraph, info: &CommitInfo, head: Option<&HeadInfo>, color: bool) -> String {
    let curr_color = info
        .branch_trace
        .map(|t| graph.all_branches[t].visual.term_color);

    let mut out = String::new();
    let head_str = "HEAD ->";

    if let Some(h) = head {
        if !h.is_branch {
            out.push(' ');
            if color {
                out.push_str(&paint(HEAD_COLOR, head_str));
            } else {
                out.push_str(head_str);
            }
        }
    }

    if !info.branches.is_empty() {
        out.push_str(" (");
        let mut ordered: Vec<usize> = info.branches.clone();
        ordered.sort_by_key(|b| match head {
            Some(h) => h.name != graph.all_branches[*b].name,
            None => false,
        });
        for (idx, b) in ordered.iter().enumerate() {
            let branch = &graph.all_branches[*b];
            if let Some(h) = head {
                if idx == 0 && h.is_branch {
                    if color {
                        out.push_str(&paint(HEAD_COLOR, head_str));
                    } else {
                        out.push_str(head_str);
                    }
                    out.push(' ');
                }
            }
            if color {
                out.push_str(&paint(branch.visual.term_color, &branch.name));
            } else {
                out.push_str(&branch.name);
            }
            if idx < info.branches.len() - 1 {
                out.push_str(", ");
            }
        }
        out.push(')');
    }

    if !info.tags.is_empty() {
        out.push_str(" [");
        for (idx, t) in info.tags.iter().enumerate() {
            let tag = &graph.all_branches[*t];
            let tag_color = curr_color.unwrap_or(tag.visual.term_color);
            let name = &tag.name[5..];
            if color {
                out.push_str(&paint(tag_color, name));
            } else {
                out.push_str(name);
            }
            if idx < info.tags.len() - 1 {
                out.push_str(", ");
            }
        }
        out.push(']');
    }

    out
}

fn str_lines(s: &str) -> Vec<String> {
    s.lines().map(|l| l.to_string()).collect()
}

fn append_wrapped(lines: &mut Vec<String>, text: String, wrapping: &Option<WrapOptions>) {
    if text.is_empty() {
        lines.push(text);
    } else if let Some(w) = wrapping {
        lines.extend(str_lines(&fill(&text, w)));
    } else {
        lines.push(text);
    }
}

fn add_line(lines: &mut Vec<String>, line: &mut String, wrapping: &Option<WrapOptions>) {
    let text = std::mem::take(line);
    append_wrapped(lines, text, wrapping);
}

fn remove_empty_lines(lines: &mut Vec<String>, line: &mut String) {
    while lines.last().map(|l| l.is_empty()).unwrap_or(false) {
        lines.pop();
    }
    if let Some(l) = lines.pop() {
        *line = l;
    }
}

fn format_date(time: Time, fmt: &str) -> String {
    let offset = FixedOffset::east_opt(time.offset_minutes() * 60)
        .unwrap_or_else(|| FixedOffset::east_opt(0).unwrap());
    match offset.timestamp_opt(time.seconds(), 0) {
        chrono::LocalResult::Single(d) => format!("{}", d.format(fmt)),
        chrono::LocalResult::Ambiguous(d, _) => format!("{}", d.format(fmt)),
        chrono::LocalResult::None => String::new(),
    }
}

fn format_relative(time: Time) -> String {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    let secs = now - time.seconds();
    let mins = secs / 60;
    let hours = secs / 3600;
    let days = secs / 86400;
    let weeks = days / 7;
    let months = days / 30;
    let years = days / 365;
    if secs < 60 {
        format!("{} seconds ago", secs)
    } else if mins < 60 {
        format!("{} minutes ago", mins)
    } else if hours < 24 {
        format!("{} hours ago", hours)
    } else if days < 7 {
        format!("{} days ago", days)
    } else if weeks < 4 {
        format!("{} weeks ago", weeks)
    } else if months < 12 {
        format!("{} months ago", months)
    } else {
        format!("{} years ago", years)
    }
}

fn hash_str(oid: &git2::Oid, abbrev: bool, hash_color: Option<u8>) -> String {
    let s = oid.to_string();
    let s = if abbrev { s[..7].to_string() } else { s };
    match hash_color {
        Some(c) => paint(c, &s),
        None => s,
    }
}

/// Formats a commit according to the given format.
pub fn format(
    commit: &Commit,
    branches: String,
    wrapping: &Option<WrapOptions>,
    hash_color: Option<u8>,
    format: &CommitFormat,
) -> Result<Vec<String>, String> {
    match format {
        CommitFormat::OneLine => Ok(format_oneline(commit, branches, wrapping, hash_color)),
        CommitFormat::Format(fmt) => Ok(format_custom(fmt, commit, branches, wrapping, hash_color)),
        other => Ok(format_multiline(commit, branches, wrapping, hash_color, other)),
    }
}

fn format_oneline(commit: &Commit, branches: String, wrapping: &Option<WrapOptions>, hash_color: Option<u8>) -> Vec<String> {
    let mut out = hash_str(&commit.id(), true, hash_color);
    out.push_str(&branches);
    out.push(' ');
    out.push_str(commit.summary().unwrap_or(""));
    match wrapping {
        Some(w) => str_lines(&fill(&out, w)),
        None => vec![out],
    }
}

fn format_multiline(
    commit: &Commit,
    branches: String,
    wrapping: &Option<WrapOptions>,
    hash_color: Option<u8>,
    format: &CommitFormat,
) -> Vec<String> {
    let mut lines = Vec::new();

    let mut out = String::from("commit ");
    out.push_str(&hash_str(&commit.id(), false, hash_color));
    out.push_str(&branches);
    append_wrapped(&mut lines, out, wrapping);

    if commit.parent_count() > 1 {
        let p0 = commit.parent_id(0).map(|o| o.to_string()).unwrap_or_default();
        let p1 = commit.parent_id(1).map(|o| o.to_string()).unwrap_or_default();
        let out = format!("Merge: {} {}", &p0[..7.min(p0.len())], &p1[..7.min(p1.len())]);
        append_wrapped(&mut lines, out, wrapping);
    }

    let author = commit.author();
    let out = format!(
        "Author: {} <{}>",
        author.name().unwrap_or(""),
        author.email().unwrap_or("")
    );
    append_wrapped(&mut lines, out, wrapping);

    if *format == CommitFormat::Full {
        let committer = commit.committer();
        let out = format!(
            "Commit: {} <{}>",
            committer.name().unwrap_or(""),
            committer.email().unwrap_or("")
        );
        append_wrapped(&mut lines, out, wrapping);
    }

    if *format != CommitFormat::Short {
        let out = format!("Date:   {}", format_date(author.when(), "%a %b %e %H:%M:%S %Y %z"));
        append_wrapped(&mut lines, out, wrapping);
    }

    if *format == CommitFormat::Short {
        lines.push(String::new());
        append_wrapped(&mut lines, format!("    {}", commit.summary().unwrap_or("")), wrapping);
        lines.push(String::new());
    } else {
        lines.push(String::new());
        let mut add_empty = true;
        for line in commit.message().unwrap_or("").lines() {
            if line.is_empty() {
                lines.push(String::new());
            } else {
                append_wrapped(&mut lines, format!("    {}", line), wrapping);
            }
            add_empty = !line.trim().is_empty();
        }
        if add_empty {
            lines.push(String::new());
        }
    }

    lines
}

fn format_custom(
    format: &str,
    commit: &Commit,
    branches: String,
    wrapping: &Option<WrapOptions>,
    hash_color: Option<u8>,
) -> Vec<String> {
    // Find all placeholder occurrences: (start, len, placeholder, mode)
    let mut replacements: Vec<(usize, usize, usize, usize)> = Vec::new();
    for (idx, name) in PLACEHOLDER_NAMES.iter().enumerate() {
        let variants = [
            format!("%{}", name),
            format!("% {}", name),
            format!("%+{}", name),
            format!("%-{}", name),
        ];
        let mut curr = 0;
        loop {
            let mut found = false;
            for (mode, var) in variants.iter().enumerate() {
                if let Some(start) = format[curr..].find(var.as_str()) {
                    replacements.push((curr + start, var.len(), idx, mode));
                    curr += start + var.len();
                    found = true;
                    break;
                }
            }
            if !found {
                break;
            }
        }
    }
    replacements.sort_by_key(|r| r.0);

    let mut lines: Vec<String> = Vec::new();
    let mut out = String::new();

    if replacements.is_empty() {
        out.push_str(format);
        add_line(&mut lines, &mut out, wrapping);
        return lines;
    }

    let mut curr = 0;
    for (start, len, idx, mode) in replacements {
        out.push_str(&format[curr..start]);
        if idx == P_NEWLINE {
            add_line(&mut lines, &mut out, wrapping);
        } else {
            match idx {
                P_BODY => {
                    let message: Vec<&str> = commit.message().unwrap_or("").lines().collect();
                    let num_parts = message.len();
                    if num_parts > 2 {
                        apply_mode(mode, &mut lines, &mut out, wrapping);
                        for (cnt, line) in message.iter().enumerate() {
                            if cnt > 1 && (cnt < num_parts - 1 || !line.is_empty()) {
                                out.push_str(line);
                                add_line(&mut lines, &mut out, wrapping);
                            }
                        }
                    } else if mode == MODE_MINUS {
                        remove_empty_lines(&mut lines, &mut out);
                    }
                }
                P_BODY_RAW => {
                    let message: Vec<&str> = commit.message().unwrap_or("").lines().collect();
                    let num_parts = message.len();
                    if !message.is_empty() {
                        apply_mode(mode, &mut lines, &mut out, wrapping);
                        for (cnt, line) in message.iter().enumerate() {
                            if cnt < num_parts - 1 || !line.is_empty() {
                                out.push_str(line);
                                add_line(&mut lines, &mut out, wrapping);
                            }
                        }
                    } else if mode == MODE_MINUS {
                        remove_empty_lines(&mut lines, &mut out);
                    }
                }
                _ => {
                    let value = expand(idx, commit, &branches, hash_color);
                    if value.is_empty() {
                        if mode == MODE_MINUS {
                            remove_empty_lines(&mut lines, &mut out);
                        }
                    } else {
                        apply_mode(mode, &mut lines, &mut out, wrapping);
                        out.push_str(&value);
                    }
                }
            }
        }
        curr = start + len;
    }
    out.push_str(&format[curr..]);
    if !out.is_empty() {
        add_line(&mut lines, &mut out, wrapping);
    }
    lines
}

fn apply_mode(mode: usize, lines: &mut Vec<String>, out: &mut String, wrapping: &Option<WrapOptions>) {
    match mode {
        MODE_SPACE => out.push(' '),
        MODE_PLUS => add_line(lines, out, wrapping),
        _ => {}
    }
    let _ = MODE_PLAIN;
}

fn expand(idx: usize, commit: &Commit, branches: &str, hash_color: Option<u8>) -> String {
    match idx {
        P_HASH => hash_str(&commit.id(), false, hash_color),
        P_HASH_ABBREV => hash_str(&commit.id(), true, hash_color),
        P_PARENTS => commit
            .parent_ids()
            .map(|o| o.to_string())
            .collect::<Vec<_>>()
            .join(" "),
        P_PARENTS_ABBREV => commit
            .parent_ids()
            .map(|o| o.to_string()[..7].to_string())
            .collect::<Vec<_>>()
            .join(" "),
        P_REFS => branches.to_string(),
        P_SUBJECT => commit.summary().unwrap_or("").to_string(),
        P_AUTHOR => commit.author().name().unwrap_or("").to_string(),
        P_AUTHOR_EMAIL => commit.author().email().unwrap_or("").to_string(),
        P_AUTHOR_DATE => format_date(commit.author().when(), "%a %b %e %H:%M:%S %Y %z"),
        P_AUTHOR_DATE_SHORT => format_date(commit.author().when(), "%F"),
        P_AUTHOR_DATE_REL => format_relative(commit.author().when()),
        P_COMMITTER => commit.committer().name().unwrap_or("").to_string(),
        P_COMMITTER_EMAIL => commit.committer().email().unwrap_or("").to_string(),
        P_COMMITTER_DATE => format_date(commit.committer().when(), "%a %b %e %H:%M:%S %Y %z"),
        P_COMMITTER_DATE_SHORT => format_date(commit.committer().when(), "%F"),
        P_COMMITTER_DATE_REL => format_relative(commit.committer().when()),
        _ => String::new(),
    }
}
EOF"}

