//! Text-based graph rendering.

use crate::graph::GitGraph;
use crate::print::colors::{paint, HASH_COLOR};
use crate::print::format::{format, format_branches};
use crate::settings::chars::*;
use crate::settings::{Characters, Settings};
use crate::wrap::WrapOptions;
use std::collections::HashMap;

const WHITE: u8 = 7;

#[derive(Clone, Copy)]
struct Cell {
    ch: u8,
    color: u8,
    pers: u8,
}

struct Grid {
    width: usize,
    height: usize,
    data: Vec<Cell>,
}

impl Grid {
    fn new(width: usize, height: usize, init: Cell) -> Grid {
        Grid {
            width,
            height,
            data: vec![init; width * height],
        }
    }

    fn idx(&self, x: usize, y: usize) -> usize {
        y * self.width + x
    }

    fn get(&self, x: usize, y: usize) -> Cell {
        self.data[self.idx(x, y)]
    }

    fn set(&mut self, x: usize, y: usize, ch: u8, color: u8, pers: u8) {
        let i = self.idx(x, y);
        self.data[i] = Cell { ch, color, pers };
    }

    fn set_opt(&mut self, x: usize, y: usize, ch: Option<u8>, color: Option<u8>, pers: Option<u8>) {
        let i = self.idx(x, y);
        let cell = &mut self.data[i];
        if let Some(c) = ch {
            cell.ch = c;
        }
        if let Some(c) = color {
            cell.color = c;
        }
        if let Some(p) = pers {
            cell.pers = p;
        }
    }

    fn reverse(&mut self) {
        self.data.reverse();
        for cell in self.data.iter_mut() {
            cell.ch = match cell.ch {
                R_U => L_D,
                L_D => R_U,
                R_D => L_U,
                L_U => R_D,
                VER_L => VER_R,
                VER_R => VER_L,
                HOR_U => HOR_D,
                HOR_D => HOR_U,
                ARR_L => ARR_R,
                ARR_R => ARR_L,
                other => other,
            };
        }
    }
}

#[derive(Clone, Copy)]
enum Occ {
    Commit(usize, usize),
    Range(usize, usize, usize, usize),
}

impl Occ {
    fn overlaps(&self, (start, end): (usize, usize)) -> bool {
        match *self {
            Occ::Commit(_, col) => start <= col && end >= col,
            Occ::Range(_, _, s, e) => s <= end && e >= start,
        }
    }
}

pub type UnicodeGraphInfo = (Vec<String>, Vec<String>, Vec<usize>);

fn create_wrapping_options(
    settings: &Settings,
    indent1: &str,
    indent2: &str,
    graph_width: usize,
) -> Option<WrapOptions> {
    match settings.wrapping {
        Some((Some(width), _, _)) => Some(WrapOptions::new(width, indent1, indent2)),
        Some((None, _, _)) => {
            if crate::term::stdout_is_tty() {
                let width = crate::term::terminal_width().unwrap_or(80);
                let width = if width > graph_width { width - graph_width } else { 1 };
                Some(WrapOptions::new(width, indent1, indent2))
            } else {
                None
            }
        }
        None => None,
    }
}

pub fn print_unicode(graph: &GitGraph, settings: &Settings) -> Result<UnicodeGraphInfo, String> {
    if graph.all_branches.is_empty() {
        return Ok((vec![], vec![], vec![]));
    }
    let num_cols = 2 * graph
        .all_branches
        .iter()
        .map(|b| b.visual.column.unwrap_or(0))
        .max()
        .unwrap()
        + 1;

    let head_idx = graph.indices.get(&graph.head.oid).cloned();

    let inserts = get_inserts(graph, settings.compact);

    let (indent1, indent2) = match settings.wrapping {
        Some((_, i1, i2)) => (" ".repeat(i1.unwrap_or(0)), " ".repeat(i2.unwrap_or(0))),
        None => (String::new(), String::new()),
    };
    let wrap_options = create_wrapping_options(settings, &indent1, &indent2, num_cols + 4);

    let mut index_map = Vec::with_capacity(graph.commits.len());
    let mut text_lines: Vec<Option<String>> = Vec::new();
    let mut offset = 0;
    for (idx, info) in graph.commits.iter().enumerate() {
        index_map.push(idx + offset);
        let cnt_inserts = match inserts.get(&idx) {
            Some(rows) => rows
                .iter()
                .filter(|row| row.iter().all(|o| matches!(o, Occ::Range(..))))
                .count(),
            None => 0,
        };

        let head = if head_idx == Some(idx) {
            Some(&graph.head)
        } else {
            None
        };

        let commit = graph
            .repository
            .find_commit(info.oid)
            .map_err(|e| e.message().to_string())?;
        let branch_str = format_branches(graph, info, head, settings.colored);
        let hash_color = if settings.colored { Some(HASH_COLOR) } else { None };
        let lines = format(&commit, branch_str, &wrap_options, hash_color, &settings.format)?;

        let num_lines = if lines.is_empty() { 0 } else { lines.len() - 1 };
        let max_inserts = std::cmp::max(cnt_inserts, num_lines);
        let add_lines = max_inserts + 1 - lines.len();

        text_lines.extend(lines.into_iter().map(Some));
        text_lines.extend((0..add_lines).map(|_| None));

        offset += max_inserts;
    }

    let mut grid = Grid::new(
        num_cols,
        graph.commits.len() + offset,
        Cell {
            ch: SPACE,
            color: WHITE,
            pers: settings.model.persistence.len() as u8 + 2,
        },
    );

    for (idx, info) in graph.commits.iter().enumerate() {
        let trace = match info.branch_trace {
            Some(t) => t,
            None => continue,
        };
        let branch = &graph.all_branches[trace];
        let column = branch.visual.column.unwrap();
        let idx_map = index_map[idx];
        let branch_color = branch.visual.term_color;

        grid.set(
            column * 2,
            idx_map,
            if info.is_merge { CIRCLE } else { DOT },
            branch_color,
            branch.persistence,
        );

        for p in 0..2 {
            let par_oid = match info.parents[p] {
                Some(o) => o,
                None => continue,
            };
            let par_idx = match graph.indices.get(&par_oid) {
                Some(&i) => i,
                None => {
                    let bottom = grid.height;
                    vline(&mut grid, (idx_map, bottom), column, branch_color, branch.persistence);
                    continue;
                }
            };
            let par_idx_map = index_map[par_idx];
            let par_info = &graph.commits[par_idx];
            let par_branch = &graph.all_branches[par_info.branch_trace.unwrap()];
            let par_column = par_branch.visual.column.unwrap();

            let (color, pers) = if info.is_merge {
                (par_branch.visual.term_color, par_branch.persistence)
            } else {
                (branch_color, branch.persistence)
            };

            if branch.visual.column == par_branch.visual.column {
                if par_idx_map > idx_map + 1 {
                    vline(&mut grid, (idx_map, par_idx_map), column, color, pers);
                }
            } else {
                let split_index = super::get_deviate_index(graph, idx, par_idx);
                let split_idx_map = index_map[split_index];
                let insert_idx = find_insert_idx(&inserts[&split_index], idx, par_idx).unwrap();
                let idx_split = split_idx_map + insert_idx;
                let is_secondary_merge = info.is_merge && p > 0;
                zig_zag_line(
                    &mut grid,
                    (idx_map, idx_split, par_idx_map),
                    (column, par_column),
                    is_secondary_merge,
                    color,
                    pers,
                );
            }
        }
    }

    if settings.reverse_commit_order {
        text_lines.reverse();
        grid.reverse();
    }

    let (g, t) = print_graph(&settings.characters, &grid, text_lines, settings.colored);
    Ok((g, t, index_map))
}

fn find_insert_idx(inserts: &[Vec<Occ>], child_idx: usize, parent_idx: usize) -> Option<usize> {
    for (insert_idx, row) in inserts.iter().enumerate() {
        for occ in row {
            if let Occ::Range(i1, i2, _, _) = *occ {
                if i1 == child_idx && i2 == parent_idx {
                    return Some(insert_idx);
                }
            }
        }
    }
    None
}

fn zig_zag_line(
    grid: &mut Grid,
    (row1, row2, row3): (usize, usize, usize),
    (col1, col2): (usize, usize),
    is_merge: bool,
    color: u8,
    pers: u8,
) {
    vline(grid, (row1, row2), col1, color, pers);
    hline(grid, row2, (col2, col1), is_merge, color, pers);
    vline(grid, (row2, row3), col2, color, pers);
}

fn new_cp(pers: u8, old_pers: u8, color: u8) -> (Option<u8>, Option<u8>) {
    if pers < old_pers {
        (Some(color), Some(pers))
    } else {
        (None, None)
    }
}

fn vline(grid: &mut Grid, (from, to): (usize, usize), column: usize, color: u8, pers: u8) {
    let x = column * 2;
    for y in (from + 1)..to {
        let cell = grid.get(x, y);
        let (nc, np) = new_cp(pers, cell.pers, color);
        match cell.ch {
            DOT | CIRCLE => {}
            HOR => grid.set_opt(x, y, Some(CROSS), Some(color), Some(pers)),
            HOR_U | HOR_D => grid.set_opt(x, y, Some(CROSS), Some(color), Some(pers)),
            CROSS | VER | VER_L | VER_R => grid.set_opt(x, y, None, nc, np),
            L_D | L_U => grid.set_opt(x, y, Some(VER_L), nc, np),
            R_D | R_U => grid.set_opt(x, y, Some(VER_R), nc, np),
            _ => grid.set_opt(x, y, Some(VER), Some(color), Some(pers)),
        }
    }
}

fn hline(grid: &mut Grid, y: usize, (from, to): (usize, usize), merge: bool, color: u8, pers: u8) {
    if from == to {
        return;
    }
    let from2 = from * 2;
    let to2 = to * 2;
    if from < to {
        for x in (from2 + 1)..to2 {
            if merge && x == to2 - 1 {
                grid.set(x, y, ARR_R, color, pers);
            } else {
                hline_mid(grid, x, y, color, pers);
            }
        }

        let left = grid.get(from2, y);
        let (nc, np) = new_cp(pers, left.pers, color);
        match left.ch {
            DOT | CIRCLE => {}
            VER => grid.set_opt(from2, y, Some(VER_R), nc, np),
            VER_L => grid.set_opt(from2, y, Some(CROSS), None, None),
            VER_R => {}
            HOR | L_U => grid.set_opt(from2, y, Some(HOR_U), nc, np),
            _ => grid.set_opt(from2, y, Some(R_D), Some(color), Some(pers)),
        }

        let right = grid.get(to2, y);
        let (nc, np) = new_cp(pers, right.pers, color);
        match right.ch {
            DOT | CIRCLE => {}
            VER => grid.set_opt(to2, y, Some(VER_L), None, None),
            VER_L | HOR_U => grid.set_opt(to2, y, None, nc, np),
            HOR | R_U => grid.set_opt(to2, y, Some(HOR_U), nc, np),
            _ => grid.set_opt(to2, y, Some(L_U), Some(color), Some(pers)),
        }
    } else {
        for x in (to2 + 1)..from2 {
            if merge && x == to2 + 1 {
                grid.set(x, y, ARR_L, color, pers);
            } else {
                hline_mid(grid, x, y, color, pers);
            }
        }

        let left = grid.get(to2, y);
        let (nc, np) = new_cp(pers, left.pers, color);
        match left.ch {
            DOT | CIRCLE => {}
            VER => grid.set_opt(to2, y, Some(VER_R), None, None),
            VER_R => grid.set_opt(to2, y, None, nc, np),
            HOR | L_U => grid.set_opt(to2, y, Some(HOR_U), nc, np),
            _ => grid.set_opt(to2, y, Some(R_U), Some(color), Some(pers)),
        }

        let right = grid.get(from2, y);
        let (nc, np) = new_cp(pers, right.pers, color);
        match right.ch {
            DOT | CIRCLE => {}
            VER => grid.set_opt(from2, y, Some(VER_L), nc, np),
            VER_R => grid.set_opt(from2, y, Some(CROSS), None, None),
            VER_L => grid.set_opt(from2, y, None, nc, np),
            HOR | R_D => grid.set_opt(from2, y, Some(HOR_D), nc, np),
            _ => grid.set_opt(from2, y, Some(L_D), Some(color), Some(pers)),
        }
    }
}

fn hline_mid(grid: &mut Grid, x: usize, y: usize, color: u8, pers: u8) {
    let cell = grid.get(x, y);
    let (nc, np) = new_cp(pers, cell.pers, color);
    match cell.ch {
        DOT | CIRCLE => {}
        VER => grid.set_opt(x, y, Some(CROSS), None, None),
        HOR | CROSS | HOR_U | HOR_D => grid.set_opt(x, y, None, nc, np),
        L_U | R_U => grid.set_opt(x, y, Some(HOR_U), nc, np),
        L_D | R_D => grid.set_opt(x, y, Some(HOR_D), nc, np),
        _ => grid.set_opt(x, y, Some(HOR), Some(color), Some(pers)),
    }
}

fn get_inserts(graph: &GitGraph, compact: bool) -> HashMap<usize, Vec<Vec<Occ>>> {
    let mut inserts: HashMap<usize, Vec<Vec<Occ>>> = HashMap::new();

    for (idx, info) in graph.commits.iter().enumerate() {
        let column = graph.all_branches[info.branch_trace.unwrap()]
            .visual
            .column
            .unwrap();
        inserts.insert(idx, vec![vec![Occ::Commit(idx, column)]]);
    }

    for (idx, info) in graph.commits.iter().enumerate() {
        let trace = match info.branch_trace {
            Some(t) => t,
            None => continue,
        };
        let branch = &graph.all_branches[trace];
        let column = branch.visual.column.unwrap();

        for p in 0..2 {
            let par_oid = match info.parents[p] {
                Some(o) => o,
                None => continue,
            };
            let par_idx = match graph.indices.get(&par_oid) {
                Some(&i) => i,
                None => continue,
            };
            let par_info = &graph.commits[par_idx];
            let par_branch = &graph.all_branches[par_info.branch_trace.unwrap()];
            let par_column = par_branch.visual.column.unwrap();
            let range = if column < par_column {
                (column, par_column)
            } else {
                (par_column, column)
            };

            if column != par_column {
                let split_index = super::get_deviate_index(graph, idx, par_idx);
                let entry = inserts.entry(split_index).or_default();
                if entry.is_empty() {
                    entry.push(vec![Occ::Range(idx, par_idx, range.0, range.1)]);
                    continue;
                }
                let mut insert_at = entry.len();
                for (insert_idx, row) in entry.iter().enumerate() {
                    let mut occ = false;
                    for other in row.iter() {
                        if other.overlaps(range) {
                            match *other {
                                Occ::Commit(target_index, _) => {
                                    if !compact || !info.is_merge || idx != target_index || p == 0 {
                                        occ = true;
                                        break;
                                    }
                                }
                                Occ::Range(o_idx, o_par_idx, _, _) => {
                                    if idx != o_idx && par_idx != o_par_idx {
                                        occ = true;
                                        break;
                                    }
                                }
                            }
                        }
                    }
                    if !occ {
                        insert_at = insert_idx;
                        break;
                    }
                }
                if insert_at == entry.len() {
                    entry.push(vec![Occ::Range(idx, par_idx, range.0, range.1)]);
                } else {
                    entry[insert_at].push(Occ::Range(idx, par_idx, range.0, range.1));
                }
            }
        }
    }
    inserts
}

fn print_graph(
    characters: &Characters,
    grid: &Grid,
    text_lines: Vec<Option<String>>,
    color: bool,
) -> (Vec<String>, Vec<String>) {
    let mut g_lines = Vec::new();
    let mut t_lines = Vec::new();
    for (row, line) in grid.data.chunks(grid.width).zip(text_lines) {
        let mut g_out = String::new();
        for cell in row {
            let ch = characters.chars[cell.ch as usize];
            if color && cell.ch != SPACE {
                g_out.push_str(&paint(cell.color, &ch.to_string()));
            } else {
                g_out.push(ch);
            }
        }
        g_lines.push(g_out);
        t_lines.push(line.unwrap_or_default());
    }
    (g_lines, t_lines)
}
