//! SVG graph rendering.

use crate::graph::GitGraph;
use crate::settings::Settings;

fn coord(index: usize, column: usize) -> (f32, f32) {
    (15.0 * (column as f32 + 1.0), 15.0 * (index as f32 + 1.0))
}

fn line(i1: usize, c1: usize, i2: usize, c2: usize, color: &str, width: u32) -> String {
    let (x1, y1) = coord(i1, c1);
    let (x2, y2) = coord(i2, c2);
    format!(
        "<line stroke=\"{}\" stroke-width=\"{}\" x1=\"{}\" x2=\"{}\" y1=\"{}\" y2=\"{}\"/>",
        color, width, x1, x2, y1, y2
    )
}

fn path(i1: usize, c1: usize, i2: usize, c2: usize, split: usize, color: &str) -> String {
    let p0 = coord(i1, c1);
    let p1 = coord(split, c1);
    let p2 = coord(split + 1, c2);
    let p3 = coord(i2, c2);
    let m = (0.5 * (p1.0 + p2.0), 0.5 * (p1.1 + p2.1));
    let d = format!(
        "M{},{} L{},{} Q{},{},{},{} Q{},{},{},{} L{},{}",
        p0.0, p0.1, p1.0, p1.1, p1.0, m.1, m.0, m.1, p2.0, m.1, p2.0, p2.1, p3.0, p3.1
    );
    format!(
        "<path d=\"{}\" fill=\"none\" stroke=\"{}\" stroke-width=\"1\"/>",
        d, color
    )
}

fn dot(index: usize, column: usize, color: &str, filled: bool) -> String {
    let (x, y) = coord(index, column);
    format!(
        "<circle cx=\"{}\" cy=\"{}\" fill=\"{}\" r=\"4\" stroke=\"{}\" stroke-width=\"1\"/>",
        x,
        y,
        if filled { color } else { "white" },
        color
    )
}

pub fn print_svg(graph: &GitGraph, settings: &Settings) -> Result<String, String> {
    let mut elements: Vec<String> = Vec::new();
    let max_idx = graph.commits.len();
    let mut max_column = 0;

    if settings.debug {
        for branch in graph.all_branches.iter() {
            if let (Some(start), Some(end)) = branch.range {
                let col = branch.visual.column.unwrap();
                elements.push(line(start, col, end, col, "cyan", 5));
            }
        }
    }

    for (idx, info) in graph.commits.iter().enumerate() {
        if let Some(trace) = info.branch_trace {
            let branch = &graph.all_branches[trace];
            let column = branch.visual.column.unwrap();
            let branch_color = &branch.visual.svg_color;
            if column > max_column {
                max_column = column;
            }
            for p in 0..2 {
                if let Some(par_oid) = info.parents[p] {
                    if let Some(&par_idx) = graph.indices.get(&par_oid) {
                        let par_info = &graph.commits[par_idx];
                        let par_branch = &graph.all_branches[par_info.branch_trace.unwrap()];
                        let par_column = par_branch.visual.column.unwrap();
                        let color = if info.is_merge {
                            &par_branch.visual.svg_color
                        } else {
                            branch_color
                        };
                        if column == par_column {
                            elements.push(line(idx, column, par_idx, par_column, color, 1));
                        } else {
                            let split = super::get_deviate_index(graph, idx, par_idx);
                            elements.push(path(idx, column, par_idx, par_column, split, color));
                        }
                    }
                }
            }
            elements.push(dot(idx, column, branch_color, !info.is_merge));
        }
    }

    let (x_max, y_max) = coord(max_idx + 1, max_column + 1);
    let mut out = format!(
        "<svg height=\"{}\" viewBox=\"0 0 {} {}\" width=\"{}\" xmlns=\"http://www.w3.org/2000/svg\">",
        y_max, x_max, y_max, x_max
    );
    for e in elements {
        out.push('\n');
        out.push_str(&e);
    }
    out.push_str("\n</svg>");
    Ok(out)
}
