mod print;
mod settings;
mod term;
mod wrap;

use clap::{Arg, ArgAction, Command};
use git2::Repository;
use graph::GitGraph;
use settings::{Characters, CommitFormat, MergePatterns, Model, Settings, Wrapping};
use std::path::PathBuf;
use std::time::Instant;

const ABOUT: &str = "Structured Git graphs for your branching model.
    https://github.com/mlange-42/git-graph

EXAMPES:
    git-graph                   -> Show graph
    git-graph --style round     -> Show graph in a different style
    git-graph --model <model>   -> Show graph using a certain <model>
    git-graph model --list      -> List available branching models
    git-graph model             -> Show repo's current branching models
    git-graph model <model>     -> Permanently set model <model> for this repo";

const FORMAT_LONG_HELP: &str = "Commit format. One of [oneline|short|medium|full|\"<string>\"].
  (First character can be used as abbreviation, e.g. '-f m')
Formatting placeholders for \"<string>\":
    %n    newline
    %H    commit hash
    %h    abbreviated commit hash
    %P    parent commit hashes
    %p    abbreviated parent commit hashes
    %d    refs (branches, tags)
    %s    commit summary
    %b    commit message body
    %B    raw body (subject and body)
    %an   author name
    %ae   author email
    %ad   author date
    %as   author date in short format 'YYYY-MM-DD'
    %cn   committer name
    %ce   committer email
    %cd   committer date
    %cs   committer date in short format 'YYYY-MM-DD'

    If you add a + (plus sign) after % of a placeholder,
       a line-feed is inserted immediately before the expansion if
       and only if the placeholder expands to a non-empty string.
    If you add a - (minus sign) after % of a placeholder, all
       consecutive line-feeds immediately preceding the expansion are
       deleted if and only if the placeholder expands to an empty string.
    If you add a ' ' (space) after % of a placeholder, a space is
       inserted immediately before the expansion if and only if
       the placeholder expands to a non-empty string.

    See also the respective git help: https://git-scm.com/docs/pretty-formats
";

fn build_cli() -> Command {
    Command::new("git-graph")
        .version("0.7.0")
        .about(ABOUT)
        .arg(
            Arg::new("path")
                .long("path")
                .short('p')
                .num_args(1)
                .help("Open repository from this path or above. Default '.'"),
        )
        .arg(
            Arg::new("skip-repo-owner-validation")
                .long("skip-repo-owner-validation")
                .action(ArgAction::SetTrue)
                .help("Skip owner validation for the repository.\nThis will turn off libgit2's owner validation, which may increase security risks.\nPlease do not disable this validation for repositories you do not trust."),
        )
        .arg(
            Arg::new("model")
                .long("model")
                .short('m')
                .num_args(1)
                .help("Branching model. Available presets are [simple|git-flow|none].\nDefault: git-flow. \nPermanently set the model for a repository with\n> git-graph model <model>"),
        )
        .arg(
            Arg::new("max-count")
                .long("max-count")
                .short('n')
                .num_args(1)
                .value_name("n")
                .help("Maximum number of commits"),
        )
        .arg(
            Arg::new("color")
                .long("color")
                .num_args(1)
                .help("Specify when colors should be used. One of [auto|always|never].\nDefault: auto."),
        )
        .arg(
            Arg::new("no-color")
                .long("no-color")
                .action(ArgAction::SetTrue)
                .help("Print without colors. Missing color support should be detected\nautomatically (e.g. when piping to a file).\nOverrides option '--color'"),
        )
        .arg(
            Arg::new("wrap")
                .long("wrap")
                .short('w')
                .num_args(0..=3)
                .help("Line wrapping for formatted commit text. Default: 'auto 0 8'\nArgument format: [<width>|auto|none[ <indent1>[ <indent2>]]]\nFor examples, consult 'git-graph --help'")
                .long_help("Line wrapping for formatted commit text. Default: 'auto 0 8'\nArgument format: [<width>|auto|none[ <indent1>[ <indent2>]]]\nExamples:\n    git-graph --wrap auto\n    git-graph --wrap auto 0 8\n    git-graph --wrap none\n    git-graph --wrap 80\n    git-graph --wrap 80 0 8\n'auto' uses the terminal's width if on a terminal."),
        )
        .arg(
            Arg::new("format")
                .long("format")
                .short('f')
                .num_args(1)
                .help("Commit format. One of [oneline|short|medium|full|\"<string>\"].\n  (First character can be used as abbreviation, e.g. '-f m')\nDefault: oneline.\nFor placeholders supported in \"<string>\", consult 'git-graph --help'")
                .long_help(FORMAT_LONG_HELP),
        )
        .arg(
            Arg::new("reverse")
                .long("reverse")
                .short('r')
                .action(ArgAction::SetTrue)
                .help("Reverse the order of commits."),
        )
        .arg(
            Arg::new("local")
                .long("local")
                .short('l')
                .action(ArgAction::SetTrue)
                .help("Show only local branches, no remotes."),
        )
        .arg(
            Arg::new("svg")
                .long("svg")
                .action(ArgAction::SetTrue)
                .help("Render graph as SVG instead of text-based."),
        )
        .arg(
            Arg::new("debug")
                .long("debug")
                .short('d')
                .action(ArgAction::SetTrue)
                .help("Additional debug output and graphics."),
        )
        .arg(
            Arg::new("sparse")
                .long("sparse")
                .short('S')
                .action(ArgAction::SetTrue)
                .help("Print a less compact graph: merge lines point to target lines\nrather than merge commits."),
        )
        .arg(
            Arg::new("style")
                .long("style")
                .short('s')
                .num_args(1)
                .help("Output style. One of [normal/thin|round|bold|double|ascii].\n  (First character can be used as abbreviation, e.g. '-s r')"),
        )
        .subcommand(
            Command::new("model")
                .about("Prints or permanently sets the branching model for a repository.")
                .arg(
                    Arg::new("model")
                        .help("The branching model to be used. Available presets are [simple|git-flow|none].\nWhen not given, prints the currently set model.")
                        .num_args(1)
                        .required(false)
                        .index(1),
                )
                .arg(
                    Arg::new("list")
                        .long("list")
                        .short('l')
                        .action(ArgAction::SetTrue)
                        .help("List all available branching models."),
                ),
        )
}

fn main() {
    std::process::exit(match run_cli() {
        Ok(()) => 0,
        Err(err) => {
            eprintln!("{}", err);
            1
        }
    });
}

fn open_repo(path: &str, skip_owner_validation: bool) -> Result<Repository, git2::Error> {
    if skip_owner_validation {
        unsafe {
            git2::opts::set_verify_owner_validation(false)?;
        }
    }
    Repository::discover(path)
}

fn run_cli() -> Result<(), String> {
    let models_dir: PathBuf = config::models_dir().unwrap_or_else(|| PathBuf::from("git-graph/models"));
    config::create_config(&models_dir)?;

    let matches = build_cli().get_matches();

    if let Some(sub) = matches.subcommand_matches("model") {
        if sub.get_flag("list") {
            println!("{}", config::available_models(&models_dir)?.join("\n"));
            return Ok(());
        }
    }

    let path = matches
        .get_one::<String>("path")
        .map(|s| s.as_str())
        .unwrap_or(".");
    let skip_owner = matches.get_flag("skip-repo-owner-validation");
    let repository = open_repo(path, skip_owner).map_err(|err| {
        format!(
            "ERROR: {}\n       Navigate into a repository before running git-graph, or use option --path",
            err.message()
        )
    })?;

    if let Some(sub) = matches.subcommand_matches("model") {
        match sub.get_one::<String>("model") {
            None => match config::repo_model_name(&repository)? {
                None => print!("No branching model set"),
                Some(m) => print!("{}", m),
            },
            Some(m) => config::set_model(&repository, m, &models_dir)?,
        }
        return Ok(());
    }

    let commit_limit = match matches.get_one::<String>("max-count") {
        None => None,
        Some(s) => match s.parse::<usize>() {
            Ok(v) => Some(v),
            Err(_) => {
                return Err(format!(
                    "Option max-count must be a positive number, but got '{}'",
                    s
                ))
            }
        },
    };

    let include_remote = !matches.get_flag("local");
    let reverse_commit_order = matches.get_flag("reverse");
    let svg = matches.get_flag("svg");
    let compact = !matches.get_flag("sparse");
    let debug = matches.get_flag("debug");

    let style = match matches.get_one::<String>("style") {
        Some(s) => Characters::from_name(s)?,
        None => Characters::thin(),
    };

    let model_def = config::get_model(
        &repository,
        matches.get_one::<String>("model").map(|s| s.as_str()),
        &models_dir,
    )?;

    let colored = if matches.get_flag("no-color") {
        false
    } else if let Some(mode) = matches.get_one::<String>("color") {
        match mode.as_str() {
            "auto" => term::stdout_is_tty(),
            "always" => true,
            "never" => false,
            other => {
                return Err(format!(
                    "Unknown color mode '{}'. Supports [auto|always|never].",
                    other
                ))
            }
        }
    } else {
        term::stdout_is_tty()
    };

    let wrapping: Wrapping = match matches.get_many::<String>("wrap") {
        Some(values) => {
            let strings: Vec<&str> = values.map(|s| s.as_str()).collect();
            if strings.is_empty() {
                Some((None, Some(0), Some(8)))
            } else {
                let parse_err = || {
                    format!(
                        "ERROR: Can't parse option --wrap '{}' to integers.",
                        strings.join(" ")
                    )
                };
                match strings[0] {
                    "none" => None,
                    "auto" => {
                        let nums = strings[1..]
                            .iter()
                            .map(|s| s.parse::<usize>())
                            .collect::<Result<Vec<_>, _>>()
                            .map_err(|_| parse_err())?;
                        Some((None, nums.first().cloned(), nums.get(1).cloned()))
                    }
                    _ => {
                        let nums = strings
                            .iter()
                            .map(|s| s.parse::<usize>())
                            .collect::<Result<Vec<_>, _>>()
                            .map_err(|_| parse_err())?;
                        Some((nums.first().cloned(), nums.get(1).cloned(), nums.get(2).cloned()))
                    }
                }
            }
        }
        None => Some((None, Some(0), Some(8))),
    };

    let format = match matches.get_one::<String>("format") {
        None => CommitFormat::OneLine,
        Some(s) => CommitFormat::parse(s),
    };

    let model = Model::compile(model_def).map_err(|e| e.to_string())?;

    let settings = Settings {
        reverse_commit_order,
        debug,
        colored,
        compact,
        include_remote,
        format,
        wrapping,
        characters: style,
        model,
        merge_patterns: MergePatterns::default(),
    };

    run(repository, &settings, svg, commit_limit)
}

fn run(repository: Repository, settings: &Settings, svg: bool, max_commits: Option<usize>) -> Result<(), String> {
    let now = Instant::now();
    let graph = GitGraph::new(repository, settings, max_commits)?;
    let duration_graph = now.elapsed().as_micros();

    if settings.debug {
        for branch in graph.all_branches.iter() {
            eprintln!(
                "{} (col {}) ({:?}) {} s: {:?}, t: {:?}",
                branch.name,
                branch.visual.column.unwrap_or(99),
                branch.range,
                if branch.is_merged { "m" } else { "" },
                branch.visual.source_order_group,
                branch.visual.target_order_group
            );
        }
    }

    let now = Instant::now();
    if svg {
        let out = print::svg::print_svg(&graph, settings)?;
        println!("{}", out);
    } else {
        let (g_lines, t_lines, _) = print::unicode::print_unicode(&graph, settings)?;
        print_unpaged(&g_lines, &t_lines);
    }
    let duration_print = now.elapsed().as_micros();

    if settings.debug {
        eprintln!(
            "Graph construction: {:.1} ms, printing: {:.1} ms ({} commits)",
            duration_graph as f32 / 1000.0,
            duration_print as f32 / 1000.0,
            graph.commits.len()
        );
    }
    Ok(())
}

fn print_unpaged(graph_lines: &[String], text_lines: &[String]) {
    use std::io::Write;
    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    for (g, t) in graph_lines.iter().zip(text_lines.iter()) {
        if writeln!(out, " {}  {}", g, t).is_err() {
            panic!("failed printing to stdout: Broken pipe (os error 32)");
        }
    }
}
