//! Detection of constructs that are valid in TOML 1.1 but not in TOML 1.0,
//! so that such model files are rejected like a strict TOML 1.0 parser would.

pub struct Violation {
    pub start: usize,
    pub end: usize,
    pub message: &'static str,
}

const MSG_NEWLINE: &str = "newlines are unsupported in inline tables, expected nothing";
const MSG_COMMENT: &str = "comments are unsupported in inline tables, expected nothing";
const MSG_TRAILING: &str = "trailing commas are not supported in inline tables, expected nothing";
pub const MSG_ESCAPE: &str =
    "missing escaped value, expected `b`, `f`, `n`, `r`, `\\`, `\"`, `u`, `U`";
const MSG_TIME: &str = "invalid time, expected `:` (MM:SS)";

#[derive(Clone, Copy, PartialEq)]
enum Ctx {
    Array,
    Inline,
}

fn is_digit(b: Option<&u8>) -> bool {
    b.map(|c| c.is_ascii_digit()).unwrap_or(false)
}

fn is_token_char(c: u8) -> bool {
    c.is_ascii_alphanumeric() || matches!(c, b':' | b'+' | b'-' | b'.' | b'_')
}

/// Checks whether a bare token is a time without seconds.
fn check_time(b: &[u8], start: usize) -> Option<Violation> {
    let mut end = start;
    while end < b.len() && is_token_char(b[end]) {
        end += 1;
    }
    // date followed by space and time
    let is_date = |s: usize| -> bool {
        s + 10 <= b.len()
            && b[s..s + 4].iter().all(|c| c.is_ascii_digit())
            && b[s + 4] == b'-'
            && b[s + 5..s + 7].iter().all(|c| c.is_ascii_digit())
            && b[s + 7] == b'-'
            && b[s + 8..s + 10].iter().all(|c| c.is_ascii_digit())
    };
    let is_hhmm = |s: usize| -> bool {
        s + 5 <= b.len()
            && b[s].is_ascii_digit()
            && b[s + 1].is_ascii_digit()
            && b[s + 2] == b':'
            && b[s + 3].is_ascii_digit()
            && b[s + 4].is_ascii_digit()
    };
    let time_start;
    if is_date(start) {
        if end == start + 10 && end + 1 < b.len() && b[end] == b' ' && is_hhmm(end + 1) {
            time_start = end + 1;
            end += 1;
            while end < b.len() && is_token_char(b[end]) {
                end += 1;
            }
        } else if end > start + 11 && (b[start + 10] == b'T' || b[start + 10] == b't') {
            time_start = start + 11;
        } else {
            return None;
        }
    } else {
        time_start = start;
    }
    if is_hhmm(time_start) && b.get(time_start + 5) != Some(&b':') {
        return Some(Violation {
            start,
            end,
            message: MSG_TIME,
        });
    }
    None
}

/// Scans a basic string starting at `i` (the opening quote). Returns the
/// index after the string, or an escape violation.
fn scan_basic(b: &[u8], mut i: usize, multi: bool) -> Result<usize, Option<Violation>> {
    i += if multi { 3 } else { 1 };
    while i < b.len() {
        let c = b[i];
        if c == b'\\' {
            let n = match b.get(i + 1) {
                Some(n) => *n,
                None => return Err(None),
            };
            match n {
                b'b' | b'f' | b'n' | b'r' | b't' | b'"' | b'\\' | b'u' | b'U' => i += 2,
                b' ' | b'\t' | b'\n' | b'\r' if multi => i += 2,
                _ => {
                    return Err(Some(Violation {
                        start: i + 1,
                        end: i + 2,
                        message: MSG_ESCAPE,
                    }))
                }
            }
            continue;
        }
        if multi {
            if b[i..].starts_with(b"\"\"\"") {
                let mut j = i + 3;
                // up to two additional quotes belong to the content
                while j < b.len() && b[j] == b'"' && j < i + 5 {
                    j += 1;
                }
                return Ok(j);
            }
        } else {
            if c == b'"' {
                return Ok(i + 1);
            }
            if c == b'\n' {
                return Err(None);
            }
        }
        i += 1;
    }
    Err(None)
}

fn scan_literal(b: &[u8], mut i: usize, multi: bool) -> Option<usize> {
    if multi {
        i += 3;
        while i < b.len() {
            if b[i..].starts_with(b"'''") {
                let mut j = i + 3;
                while j < b.len() && b[j] == b'\'' && j < i + 5 {
                    j += 1;
                }
                return Some(j);
            }
            i += 1;
        }
        None
    } else {
        i += 1;
        while i < b.len() {
            if b[i] == b'\'' {
                return Some(i + 1);
            }
            if b[i] == b'\n' {
                return None;
            }
            i += 1;
        }
        None
    }
}

/// Finds the first TOML 1.0 violation in the input, if any.
pub fn scan(src: &str) -> Option<Violation> {
    let b = src.as_bytes();
    let mut i = 0;
    let mut stack: Vec<Ctx> = Vec::new();
    // per inline table: position of a pending trailing comma
    let mut pending_comma: Vec<Option<usize>> = Vec::new();
    let mut expect_value = false;

    while i < b.len() {
        let c = b[i];
        let top = stack.last().cloned();
        match c {
            b' ' | b'\t' => {
                i += 1;
            }
            b'\r' | b'\n' => {
                if top == Some(Ctx::Inline) {
                    return Some(Violation {
                        start: i,
                        end: i + 1,
                        message: MSG_NEWLINE,
                    });
                }
                if top.is_none() {
                    expect_value = false;
                }
                i += 1;
            }
            b'#' => {
                let start = i;
                while i < b.len() && b[i] != b'\n' && b[i] != b'\r' {
                    i += 1;
                }
                if top == Some(Ctx::Inline) {
                    return Some(Violation {
                        start,
                        end: i,
                        message: MSG_COMMENT,
                    });
                }
            }
            b'"' => {
                if let Some(pc) = pending_comma.last_mut() {
                    *pc = None;
                }
                let multi = b[i..].starts_with(b"\"\"\"");
                match scan_basic(b, i, multi) {
                    Ok(n) => i = n,
                    Err(v) => return v,
                }
            }
            b'\'' => {
                if let Some(pc) = pending_comma.last_mut() {
                    *pc = None;
                }
                let multi = b[i..].starts_with(b"'''");
                match scan_literal(b, i, multi) {
                    Some(n) => i = n,
                    None => return None,
                }
            }
            b'[' => {
                if top.is_none() && !expect_value {
                    // table header: skip to end of line
                    i += 1;
                    while i < b.len() && b[i] != b'\n' {
                        match b[i] {
                            b'"' => match scan_basic(b, i, false) {
                                Ok(n) => i = n,
                                Err(v) => return v,
                            },
                            b'\'' => match scan_literal(b, i, false) {
                                Some(n) => i = n,
                                None => return None,
                            },
                            b'#' => break,
                            _ => i += 1,
                        }
                    }
                } else {
                    if let Some(pc) = pending_comma.last_mut() {
                        *pc = None;
                    }
                    stack.push(Ctx::Array);
                    i += 1;
                }
            }
            b']' => {
                if top == Some(Ctx::Array) {
                    stack.pop();
                } else {
                    return None;
                }
                i += 1;
            }
            b'{' => {
                if let Some(pc) = pending_comma.last_mut() {
                    *pc = None;
                }
                stack.push(Ctx::Inline);
                pending_comma.push(None);
                expect_value = false;
                i += 1;
            }
            b'}' => {
                if top == Some(Ctx::Inline) {
                    if let Some(Some(pos)) = pending_comma.pop() {
                        return Some(Violation {
                            start: pos,
                            end: pos + 1,
                            message: MSG_TRAILING,
                        });
                    }
                    stack.pop();
                } else {
                    return None;
                }
                i += 1;
            }
            b',' => {
                if top == Some(Ctx::Inline) {
                    if let Some(pc) = pending_comma.last_mut() {
                        *pc = Some(i);
                    }
                    expect_value = false;
                }
                i += 1;
            }
            b'=' => {
                expect_value = true;
                i += 1;
            }
            _ => {
                if let Some(pc) = pending_comma.last_mut() {
                    *pc = None;
                }
                let in_value = top == Some(Ctx::Array) || expect_value;
                if in_value && c.is_ascii_digit() && is_digit(b.get(i + 1)) {
                    if let Some(v) = check_time(b, i) {
                        return Some(v);
                    }
                }
                // skip the bare token
                let start = i;
                while i < b.len() && is_token_char(b[i]) {
                    i += 1;
                }
                if i == start {
                    i += 1;
                }
            }
        }
    }
    None
}
