        return None;
    }
    String::from_utf8_lossy(&out.stdout).trim().parse::<usize>().ok()
}

/// Returns the width of the terminal in columns.
pub fn terminal_width() -> Option<usize> {
    use std::os::unix::io::AsRawFd;
    let tty = std::fs::File::open("/dev/tty");
    let fd = match &tty {
